-- Schema extracted from F1 Manager 24 save file (save-sample.db)
-- 328 tables, 2 views, 1 indexes

-- ============ TABLES ============

CREATE TABLE Board_Confidence (Season INTEGER PRIMARY KEY NOT NULL DEFAULT 2022,Confidence INTEGER NOT NULL,FOREIGN KEY (Season) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Board_Confidence_FinanceHistory (Day INTEGER PRIMARY KEY NOT NULL,Overdraft bigint(20) DEFAULT 0,Overspend bigint(20) DEFAULT 0);

CREATE TABLE Board_Confidence_RaceHistory (Day INTEGER PRIMARY KEY NOT NULL,TrackID INTEGER NOT NULL,Performance INTEGER NOT NULL,FOREIGN KEY (Performance) REFERENCES Board_Enum_BoardPerformance (Value),FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID));

CREATE TABLE Board_Confidence_RaceMods (MinPosDelta decimal(3,1) NOT NULL,MaxPosDelta decimal(3,1) NOT NULL,ConfidenceMod INTEGER NOT NULL,BoardPerformance INTEGER NOT NULL,PRIMARY KEY (MinPosDelta,MaxPosDelta),FOREIGN KEY (BoardPerformance) REFERENCES Board_Enum_BoardPerformance (Value));

CREATE TABLE Board_Enum_BoardPerformance (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Board_Enum_ConfidenceLevels (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,UpperBound INTEGER NOT NULL,ReviewBonus INTEGER NOT NULL DEFAULT 0);

CREATE TABLE Board_Enum_ObjectiveStates (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,ConfidenceModFromLongTermObj INTEGER DEFAULT NULL,BoardPerformanceFromLongTermObj INTEGER DEFAULT NULL,NumBoardPerformanceFromLongTermObj INTEGER DEFAULT NULL,ConfidenceModFromSeasonObj INTEGER DEFAULT NULL,BoardPerformanceFromSeasonObj INTEGER DEFAULT NULL,NumBoardPerformanceFromSeasonObj INTEGER DEFAULT NULL,FOREIGN KEY (BoardPerformanceFromLongTermObj) REFERENCES Board_Enum_BoardPerformance (Value),FOREIGN KEY (BoardPerformanceFromSeasonObj) REFERENCES Board_Enum_BoardPerformance (Value));

CREATE TABLE Board_Enum_ObjectiveTypes (Value INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL, MinTeamRating INTEGER NOT NULL, MaxTeamRating INTEGER NOT NULL, ExpectedRank INTEGER NOT NULL);

CREATE TABLE Board_Objectives (TeamID INTEGER NOT NULL,Type INTEGER NOT NULL,StartYear INTEGER NOT NULL,TargetEndYear INTEGER NOT NULL,State INTEGER NOT NULL DEFAULT 0,EndYear INTEGER DEFAULT NULL,PRIMARY KEY (TeamID,StartYear),FOREIGN KEY (State) REFERENCES Board_Enum_ObjectiveStates (Value),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID),FOREIGN KEY (Type) REFERENCES Board_Enum_ObjectiveTypes (Value));

CREATE TABLE Board_Payments (SeasonExpectation INTEGER UNIQUE PRIMARY KEY NOT NULL,Budget bigint(20) NOT NULL DEFAULT 0);

CREATE TABLE Board_SeasonObjectives (TeamID INTEGER NOT NULL,SeasonID INTEGER NOT NULL,TargetPos INTEGER NOT NULL,State INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (TeamID,SeasonID),FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (State) REFERENCES Board_Enum_ObjectiveStates (Value),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Board_TeamRating (TeamID INTEGER NOT NULL, SeasonID INTEGER NOT NULL, PtsFromConstructorResults INTEGER NOT NULL, PtsFromDriverResults INTEGER NOT NULL, PtsFromSeasonsEntered INTEGER NOT NULL, PtsFromChampionshipsWon INTEGER NOT NULL, PtsFromNewTeamHype INTEGER NOT NULL, PRIMARY KEY (TeamID, SeasonID), FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Board_TeamRating_ChampionshipPosPts (Pos INTEGER UNIQUE PRIMARY KEY NOT NULL, PtsFromConstructor INTEGER DEFAULT NULL, PtsFromBestDriver INTEGER DEFAULT NULL);

CREATE TABLE Board_TeamRating_RelevancyMultipliers (NumSeasonsAgo INTEGER PRIMARY KEY NOT NULL, Multiplier decimal (3, 2) NOT NULL);

CREATE TABLE Building_Enum_Effects (Effect INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,Sublabel TEXT DEFAULT NULL);

CREATE TABLE Building_Enum_Groups (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL UNIQUE, Name TEXT NOT NULL);

CREATE TABLE Building_Enum_States (State INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Building_Enum_Types (Type INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL, Name TEXT NOT NULL, BuildingGroup INTEGER REFERENCES Building_Enum_Groups (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Building_Furbishment (Value INTEGER NOT NULL PRIMARY KEY, Name TEXT NOT NULL, EffectivenessScalar decimal (3, 2) NOT NULL, DegrationThreshold decimal (3, 2) NOT NULL);

CREATE TABLE Buildings (BuildingID INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL,Type INTEGER NOT NULL,Name TEXT NOT NULL,UpgradeLevel INTEGER NOT NULL DEFAULT 0,UpkeepCost bigint(20) NOT NULL DEFAULT 0,UpkeepAffectsCostCap INTEGER DEFAULT 0,ConstructionCost bigint(20) NOT NULL DEFAULT 0,ConstructionWork INTEGER NOT NULL DEFAULT 0,RefurbishCost bigint(20) NOT NULL DEFAULT 0,RefurbishWork INTEGER NOT NULL DEFAULT 0,RequiredType INTEGER DEFAULT NULL,RequiredLevel INTEGER DEFAULT NULL,DegradationSpeed decimal(10,5) NOT NULL DEFAULT 0.00050,FOREIGN KEY (RequiredType) REFERENCES Building_Enum_Types (Type),FOREIGN KEY (Type) REFERENCES Building_Enum_Types (Type));

CREATE TABLE Buildings_Effects (BuildingID INTEGER NOT NULL,EffectID INTEGER NOT NULL,Value decimal(8,3) DEFAULT NULL,PRIMARY KEY (BuildingID,EffectID),FOREIGN KEY (BuildingID) REFERENCES Buildings (BuildingID),FOREIGN KEY (EffectID) REFERENCES Building_Enum_Effects (Effect));

CREATE TABLE Buildings_Effects_Parts (BuildingType INTEGER NOT NULL,PartType INTEGER NOT NULL,StatID INTEGER NOT NULL,Weight decimal(10,3) NOT NULL,PRIMARY KEY (BuildingType,PartType,StatID),FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value),FOREIGN KEY (StatID) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE,FOREIGN KEY (BuildingType) REFERENCES Building_Enum_Types (Type));

CREATE TABLE Buildings_HQ (BuildingID INTEGER NOT NULL, BuildingType INTEGER NOT NULL, TeamID INTEGER NOT NULL, DegradationValue decimal (4, 3) NOT NULL DEFAULT (1), BuildingState INTEGER NOT NULL, WorkDone INTEGER, PRIMARY KEY (BuildingType, TeamID), FOREIGN KEY (BuildingID) REFERENCES Buildings (BuildingID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (BuildingState) REFERENCES Building_Enum_States (State) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (BuildingType) REFERENCES Building_Enum_Types (Type) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Buildings_HQ_History (BuildingID INTEGER NOT NULL REFERENCES Buildings (BuildingID) ON DELETE CASCADE ON UPDATE RESTRICT, Type INTEGER NOT NULL REFERENCES Building_Enum_Types (Type) ON DELETE CASCADE ON UPDATE RESTRICT, TeamID INTEGER REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, DayConstructed INTEGER NOT NULL, PRIMARY KEY (BuildingID, Type, TeamID));

CREATE TABLE Calendar_LastActivityDates (LastScoutDate INTEGER PRIMARY KEY NOT NULL DEFAULT 0,LastEngineerDate INTEGER NOT NULL DEFAULT 0,LastDesignProjectDate INTEGER NOT NULL DEFAULT 0,LastResearchProjectDate INTEGER NOT NULL DEFAULT 0);

CREATE TABLE Countries (CountryID INTEGER PRIMARY KEY NOT NULL UNIQUE, Name TEXT UNIQUE NOT NULL, NationalityWeight decimal (4, 3) NOT NULL DEFAULT 0.01, StaffNameLocale INTEGER NOT NULL, Population INTEGER NOT NULL DEFAULT 0, EnumName INTEGER NOT NULL, MarketAppetite INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (StaffNameLocale) REFERENCES Staff_Enum_NameLocales (Value));

CREATE TABLE Countries_RaceRecord (CountryID INTEGER NOT NULL REFERENCES Countries (CountryID) ON UPDATE RESTRICT ON DELETE CASCADE, Formula INTEGER NOT NULL DEFAULT 1, TotalRaces INTEGER NOT NULL DEFAULT 0, TotalStarts INTEGER NOT NULL DEFAULT 0, TotalPodiums INTEGER NOT NULL DEFAULT 0, TotalWins INTEGER NOT NULL DEFAULT 0, TotalChampionships INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (CountryID, Formula));

CREATE TABLE Custom_2025_SeasonMod (key TEXT PRIMARY KEY, value TEXT);

CREATE TABLE Custom_2026_SeasonMod (key TEXT PRIMARY KEY, value TEXT);

CREATE TABLE Custom_DriverOfTheDay_Ranking (
      Season    INTEGER NOT NULL,
      RaceID    INTEGER NOT NULL,
      Rank      INTEGER NOT NULL,   -- 1,2,3...
      DriverID  INTEGER NOT NULL,
      Name      TEXT    NOT NULL,
      Score     REAL    NOT NULL,
      TeamID    INTEGER NOT NULL,
      PRIMARY KEY (Season, RaceID, Rank)
    );

CREATE TABLE Custom_Engine_Allocations (
            teamId INTEGER,
            engineId INTEGER
            
          );

CREATE TABLE Custom_Engine_Progression (
          SeasonID INTEGER NOT NULL,
          RaceID INTEGER NOT NULL,
          EngineID INTEGER NOT NULL,
          Power REAL NOT NULL,
          Source TEXT NULL,
          PRIMARY KEY (SeasonID, RaceID, EngineID)
        );

CREATE TABLE Custom_Engine_Regulation_State (
              id INTEGER PRIMARY KEY CHECK (id = 1),
              lastSeasonApplied INTEGER
            );

CREATE TABLE Custom_Engines_List (
            engineId INTEGER PRIMARY KEY,
            name TEXT
          );

CREATE TABLE Custom_Engines_Stats (
            engineId INTEGER,
            designId INTEGER,
            partStat INTEGER,
            unitValue REAL,
            Value REAL,
            PRIMARY KEY (engineId, designId, partStat)
        );

CREATE TABLE Custom_News_State (key TEXT PRIMARY KEY, value TEXT);

CREATE TABLE Custom_Save_Config (
            key TEXT PRIMARY KEY,
            value TEXT
          );

CREATE TABLE Difficulty_Enum_Option(Value INTEGER PRIMARY KEY NOT NULL, Name TEXT);

CREATE TABLE Difficulty_RaceSim (AIPerformance INTEGER PRIMARY KEY NOT NULL DEFAULT (2) REFERENCES Difficulty_Enum_Option (Value));

CREATE TABLE Difficulty_TeamManagement (AIDesignExpertiseGain INTEGER PRIMARY KEY NOT NULL DEFAULT (2) REFERENCES Difficulty_Enum_Option (Value));

CREATE TABLE Effects_ActiveEffects (ActiveEffectID INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, Effect INTEGER NOT NULL REFERENCES Effects_Enum_Effect (Value) ON DELETE CASCADE ON UPDATE RESTRICT, EffectType INTEGER REFERENCES Effects_Enum_EffectType (Type) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, Source INTEGER REFERENCES Effects_Enum_Source (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, Value DECIMAL (3, 2) NOT NULL, ReferenceID INTEGER, SubReferenceID INTEGER, EndDay INTEGER);

CREATE TABLE Effects_Enum_Effect (Value INTEGER PRIMARY KEY NOT NULL, Name text NOT NULL);

CREATE TABLE Effects_Enum_EffectType (Type INTEGER PRIMARY KEY NOT NULL, Name text NOT NULL);

CREATE TABLE Effects_Enum_Source (Value INTEGER PRIMARY KEY NOT NULL, Name STRING NOT NULL);

CREATE TABLE EventLog_Enum_EntryType (EntryType INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE EventLogs (EventLogID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,EntryType INTEGER NOT NULL,ReferenceID INTEGER NOT NULL,Day INTEGER NOT NULL,FOREIGN KEY (EntryType) REFERENCES EventLog_Enum_EntryType (EntryType));

CREATE TABLE Fanfares (FanfareType INTEGER NOT NULL,ReferenceID INTEGER NOT NULL DEFAULT -1,SubReferenceID INTEGER NOT NULL DEFAULT -1,PRIMARY KEY (FanfareType,ReferenceID,SubReferenceID));

CREATE TABLE Fanfares_Enum_Types (Type INTEGER PRIMARY KEY NOT NULL,Name TEXT DEFAULT NULL);

CREATE TABLE Finance_Constants (StartingCashThreshold0 INTEGER PRIMARY KEY NOT NULL,StartingCashThreshold1 INTEGER NOT NULL);

CREATE TABLE Finance_Enum_BudgetCategory (Value INTEGER PRIMARY KEY UNIQUE NOT NULL, Name TEXT UNIQUE NOT NULL);

CREATE TABLE Finance_Enum_TransactionType (TransactionType INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,Name text DEFAULT NULL);

CREATE TABLE Finance_TeamBalance (TeamID INTEGER UNIQUE NOT NULL,Balance bigint(20) NOT NULL,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Finance_TeamBudget (TeamID INTEGER NOT NULL REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, SeasonID INTEGER NOT NULL REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, InitialBalance bigint (20) NOT NULL DEFAULT (0), FinalBalance bigint (20) DEFAULT (0) NOT NULL, ProjectedIncome bigint (20) NOT NULL DEFAULT (0), ProjectedSpending bigint (20) NOT NULL DEFAULT (0), TotalIncome bigint (20) DEFAULT (0) NOT NULL, TotalSpending bigint (20) DEFAULT (0) NOT NULL, StrategyPresetID TEXT, LastRebalanceDay INTEGER DEFAULT (- 1), PRIMARY KEY (TeamID, SeasonID));

CREATE TABLE Finance_TeamBudget_SpendingBuckets (TeamID INTEGER NOT NULL, SeasonID INTEGER NOT NULL, Category INTEGER NOT NULL, IsReserved INTEGER DEFAULT (0) NOT NULL, EstimatedSpending bigint (20) DEFAULT (0) NOT NULL, AllocatedAmount bigint (20) DEFAULT (0) NOT NULL, RemainingAmount bigint DEFAULT (0) NOT NULL, Weight decimal (3, 2) DEFAULT (0), UsedAmount bigint (20) DEFAULT (0), PRIMARY KEY (TeamID, SeasonID, Category), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (Category) REFERENCES Finance_Enum_BudgetCategory (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Finance_Transactions (TeamID INTEGER NOT NULL,Day INTEGER NOT NULL DEFAULT 0,Value bigint(20) NOT NULL DEFAULT 0,TransactionType INTEGER NOT NULL,Reference INTEGER DEFAULT NULL,AffectsCostCap INTEGER DEFAULT 0,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID),FOREIGN KEY (TransactionType) REFERENCES Finance_Enum_TransactionType (TransactionType));

CREATE TABLE Mail_ChainSequences (ChainType INTEGER NOT NULL, ReferenceID INTEGER DEFAULT (- 1) NOT NULL, SubReferenceID INTEGER NOT NULL DEFAULT (- 1), Position INTEGER NOT NULL, MailID INTEGER NOT NULL REFERENCES Mail_Inbox (MailID) ON DELETE CASCADE ON UPDATE RESTRICT, PRIMARY KEY (ChainType, ReferenceID, SubReferenceID, Position), FOREIGN KEY (ChainType, ReferenceID, SubReferenceID) REFERENCES Mail_Chains (ChainType, ReferenceID, SubReferenceID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Mail_Chains (ChainType INTEGER NOT NULL REFERENCES Mail_Enum_ChainType (Value) ON DELETE CASCADE ON UPDATE RESTRICT, ReferenceID INTEGER NOT NULL DEFAULT (- 1), SubReferenceID INTEGER NOT NULL DEFAULT (- 1), LastTriggerDay INTEGER NOT NULL, Cooldown INTEGER NOT NULL, Completed INTEGER NOT NULL DEFAULT (0), PRIMARY KEY (ChainType, ReferenceID, SubReferenceID));

CREATE TABLE Mail_Dilemmas_ResponseEffects (MailID INTEGER NOT NULL,ResponseNumber INTEGER NOT NULL,EffectNumber INTEGER NOT NULL,Label text NOT NULL,Status text NOT NULL,Icon text DEFAULT NULL,ReferenceID INTEGER NOT NULL DEFAULT -1,SubReferenceID INTEGER DEFAULT NULL,Effect INTEGER NOT NULL,EffectType INTEGER NOT NULL,Value decimal(10,6) NOT NULL,Duration INTEGER DEFAULT NULL,Hidden INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (MailID,ResponseNumber,EffectNumber),FOREIGN KEY (MailID, ResponseNumber) REFERENCES Mail_Dilemmas_Responses (MailID, ResponseNumber) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Mail_Dilemmas_Responses (MailID INTEGER NOT NULL,ResponseNumber INTEGER NOT NULL,Selected INTEGER NOT NULL DEFAULT 0,Label text NOT NULL,Icon text DEFAULT NULL,PRIMARY KEY (MailID,ResponseNumber),FOREIGN KEY (MailID) REFERENCES Mail_Inbox (MailID) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Mail_Enum_Attachment_StatType (Type INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Mail_Enum_Attachment_Status (Status INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Mail_Enum_BlockType (Type INTEGER UNIQUE PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Mail_Enum_ChainType (Value INTEGER PRIMARY KEY NOT NULL, Name STRING NOT NULL);

CREATE TABLE Mail_Enum_Event (Value INTEGER PRIMARY KEY NOT NULL, Name STRING NOT NULL);

CREATE TABLE Mail_Enum_Trigger (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Mail_EventPool (Event INTEGER PRIMARY KEY REFERENCES Mail_Enum_Event (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Mail_EventPool_Cooldown (NextTriggerDay INTEGER PRIMARY KEY UNIQUE NOT NULL);

CREATE TABLE Mail_Inbox (MailID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, Day INTEGER DEFAULT NULL, Subject text DEFAULT NULL, Icon text DEFAULT NULL, ReferenceID INTEGER NOT NULL DEFAULT -1, SenderName text DEFAULT NULL, SenderSubLabel text DEFAULT NULL, SenderIcon text DEFAULT NULL, StretchOddAttachments INTEGER DEFAULT (0), Filters INTEGER NOT NULL DEFAULT 0, Unread INTEGER NOT NULL DEFAULT 1, BlockType INTEGER NOT NULL DEFAULT 0, InitialBlockType INTEGER NOT NULL DEFAULT 0, OnReadTrigger INTEGER NOT NULL DEFAULT 0, Flagged INTEGER DEFAULT 0, FOREIGN KEY (BlockType) REFERENCES Mail_Enum_BlockType (Type) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (InitialBlockType) REFERENCES Mail_Enum_BlockType (Type) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (OnReadTrigger) REFERENCES Mail_Enum_Trigger (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Mail_Inbox_AttachmentStats (AttachmentStatID INTEGER PRIMARY KEY NOT NULL, AttachmentID INTEGER NOT NULL, Name TEXT NOT NULL, Type INTEGER NOT NULL, Status INTEGER NOT NULL, Icon TEXT DEFAULT NULL, Modifiers TEXT DEFAULT NULL, FOREIGN KEY (AttachmentID) REFERENCES Mail_Inbox_Attachments (AttachmentID) ON DELETE CASCADE, FOREIGN KEY (Type) REFERENCES Mail_Enum_Attachment_StatType (Type), FOREIGN KEY (Status) REFERENCES Mail_Enum_Attachment_Status (Status));

CREATE TABLE Mail_Inbox_AttachmentStats_StringValues (AttachmentStatID INTEGER NOT NULL REFERENCES Mail_Inbox_AttachmentStats (AttachmentStatID) ON DELETE CASCADE ON UPDATE RESTRICT, Number INTEGER NOT NULL, Value STRING NOT NULL, PRIMARY KEY (AttachmentStatID, Number));

CREATE TABLE Mail_Inbox_AttachmentStats_Values (AttachmentStatID INTEGER REFERENCES Mail_Inbox_AttachmentStats (AttachmentStatID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, Number INTEGER NOT NULL, Value DECIMAL (10, 5) NOT NULL, NumOfDecimals INTEGER NOT NULL, PRIMARY KEY (AttachmentStatID, Number));

CREATE TABLE Mail_Inbox_Attachments (AttachmentID INTEGER PRIMARY KEY NOT NULL,MailID INTEGER NOT NULL,Name TEXT NOT NULL,FOREIGN KEY (MailID) REFERENCES Mail_Inbox (MailID) ON DELETE CASCADE);

CREATE TABLE Mail_Inbox_Links (MailID INTEGER NOT NULL,Address TEXT NOT NULL,LinkNumber INTEGER NOT NULL,Label TEXT NOT NULL,Icon TEXT DEFAULT NULL,PRIMARY KEY (MailID,Address),FOREIGN KEY (MailID) REFERENCES Mail_Inbox (MailID) ON DELETE CASCADE);

CREATE TABLE Mail_Inbox_Sections (MailID INTEGER REFERENCES Mail_Inbox (MailID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, Number INTEGER NOT NULL, Title TEXT, Text TEXT, Image TEXT, ImageCaption TEXT, PRIMARY KEY (MailID, Number));

CREATE TABLE Notifications_DisplayOptions (PriorityBand INTEGER PRIMARY KEY NOT NULL,DisplayOptionID INTEGER NOT NULL,FOREIGN KEY (DisplayOptionID) REFERENCES Notifications_Enum_DisplayOptions (DisplayOption));

CREATE TABLE Notifications_Enum_DisplayOptions (DisplayOption INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Onboarding_Enum_HelpArticles (HelpArticleID INTEGER PRIMARY KEY NOT NULL,Name TEXT UNIQUE NOT NULL);

CREATE TABLE Onboarding_Enum_PlayerStepTypes (PlayerStepType INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Onboarding_HelpArticleContents (HelpContentID INTEGER PRIMARY KEY NOT NULL,HelpArticleID INTEGER NOT NULL,Name TEXT NOT NULL,FOREIGN KEY (HelpArticleID) REFERENCES Onboarding_Enum_HelpArticles (HelpArticleID));

CREATE TABLE Onboarding_Tutorial_Enum_IsActiveSettings (IsActiveSetting INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL);

CREATE TABLE Onboarding_Tutorial_Enum_Objectives (Objective INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,State INTEGER NOT NULL,FOREIGN KEY (State) REFERENCES Onboarding_Tutorial_Enum_States (State));

CREATE TABLE Onboarding_Tutorial_Enum_Sequences (SequenceID INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL, State INTEGER NOT NULL DEFAULT (0), CurrentStep TEXT DEFAULT NULL, PlayerStepReferenceID INTEGER DEFAULT NULL, PlayerStepType INTEGER DEFAULT NULL, StaffID INTEGER, UnlockDay INTEGER NOT NULL DEFAULT (0), FOREIGN KEY (PlayerStepType) REFERENCES Onboarding_Enum_PlayerStepTypes (PlayerStepType), FOREIGN KEY (State) REFERENCES Onboarding_Tutorial_Enum_States (State), FOREIGN KEY (StaffID) REFERENCES Staff_BasicData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Onboarding_Tutorial_Enum_States (State INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Onboarding_Tutorial_RestrictedActions (TutorialIsActiveSetting INTEGER PRIMARY KEY, BlockDaysAdvancement INTEGER NOT NULL, FOREIGN KEY (TutorialIsActiveSetting) REFERENCES Onboarding_Tutorial_Enum_IsActiveSettings (IsActiveSetting));

CREATE TABLE Parts_CarLoadout (TeamID INTEGER NOT NULL, LoadoutID INTEGER NOT NULL, PartType INTEGER NOT NULL, DesignID  INTEGER DEFAULT NULL, ItemID INTEGER DEFAULT NULL, PRIMARY KEY (TeamID, LoadoutID, PartType), FOREIGN KEY (DesignID) REFERENCES Parts_Designs (DesignID) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (ItemID) REFERENCES Parts_Items (ItemID) ON DELETE SET NULL, FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Parts_DamageEffects (PartType INTEGER NOT NULL,DamageState INTEGER NOT NULL,EffectString TEXT NOT NULL,EffectStrength INTEGER NOT NULL,PRIMARY KEY (PartType,DamageState,EffectString),FOREIGN KEY (DamageState) REFERENCES Parts_Enum_DamageStates (Value),FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value));

CREATE TABLE Parts_DesignFocusPresets (Preset INTEGER NOT NULL, PartType INTEGER NOT NULL, PartStat INTEGER NOT NULL, DesignFocus decimal (2, 1) NOT NULL DEFAULT 0.5, PRIMARY KEY (Preset, PartType, PartStat), FOREIGN KEY (PartStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE, FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value), FOREIGN KEY (Preset) REFERENCES Parts_Enum_EmphasisPresets (Value));

CREATE TABLE Parts_DesignHistoryData (DesignID INTEGER PRIMARY KEY NOT NULL,RaceUsage INTEGER NOT NULL DEFAULT 0,RaceWins INTEGER NOT NULL DEFAULT 0,RacePodiums INTEGER NOT NULL DEFAULT 0,NumPartsUsed INTEGER NOT NULL DEFAULT 0,FOREIGN KEY (DesignID) REFERENCES Parts_Designs (DesignID) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Parts_Designs (DesignID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,PartType INTEGER NOT NULL,DesignWork INTEGER NOT NULL DEFAULT 0,DesignWorkMax INTEGER NOT NULL DEFAULT 10000,DayCreated INTEGER NOT NULL DEFAULT -1,DayCompleted INTEGER NOT NULL DEFAULT -1,ChiefDesignerID INTEGER DEFAULT NULL,WindTunnelTime INTEGER NOT NULL DEFAULT 0,CFD INTEGER NOT NULL DEFAULT 0,DesignCost INTEGER NOT NULL DEFAULT 1000000,BuildCost bigint(20) NOT NULL DEFAULT 1000000,BuildWorkMax INTEGER NOT NULL DEFAULT 2000,ValidFrom INTEGER NOT NULL DEFAULT 2022,DesignSpeed INTEGER NOT NULL DEFAULT 0,PartKnowledge decimal(8,2) NOT NULL DEFAULT 0.00,ManufactureCount INTEGER NOT NULL DEFAULT 0,DesignNumber INTEGER NOT NULL DEFAULT 0,DesignType INTEGER NOT NULL DEFAULT 1,TeamID INTEGER NOT NULL, LastCompletedProjectManufactureCount INTEGER NOT NULL DEFAULT 0,FOREIGN KEY (DesignType) REFERENCES Parts_Enum_DesignTypes (Value),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID),FOREIGN KEY (DesignSpeed) REFERENCES Parts_Enum_DevSpeeds (Value),FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value));

CREATE TABLE Parts_Designs_BuildingEffects
(
    DesignID INTEGER NOT NULL, 
    PartStat INTEGER NOT NULL, 
    BuildingType INTEGER NOT NULL, 
    Value DECIMAL (8, 4) DEFAULT 0.0,
    PRIMARY KEY (DesignID, PartStat, BuildingType),
    FOREIGN KEY (DesignID, PartStat) REFERENCES Parts_Designs_StatValues (DesignID, PartStat) ON DELETE CASCADE ON UPDATE RESTRICT,
    FOREIGN KEY (BuildingType) REFERENCES Building_Enum_Types (Type) ON DELETE CASCADE ON UPDATE RESTRICT
);

CREATE TABLE Parts_Designs_StaffEffects
(
    DesignID INTEGER NOT NULL, 
    PartStat INTEGER NOT NULL, 
    StaffType INTEGER NOT NULL, 
    Value DECIMAL (8, 4) DEFAULT 0.0,
    PRIMARY KEY (DesignID, PartStat, StaffType),
    FOREIGN KEY (DesignID, PartStat) REFERENCES Parts_Designs_StatValues (DesignID, PartStat) ON DELETE CASCADE ON UPDATE RESTRICT,
    FOREIGN KEY (StaffType) REFERENCES Staff_Enum_StaffType (StaffType) ON DELETE CASCADE ON UPDATE RESTRICT
);

CREATE TABLE Parts_Designs_StatValues (DesignID INTEGER NOT NULL, PartStat INTEGER NOT NULL, Value decimal (8, 4) NOT NULL, UnitValue decimal (8, 4) NOT NULL DEFAULT 0.0, DesignFocus decimal (8, 4) NOT NULL DEFAULT 0.0, ExpertiseGain decimal (8, 4) NOT NULL DEFAULT 0.0, ExpertiseEffect decimal (8, 4) NOT NULL DEFAULT 0.0, PRIMARY KEY (DesignID, PartStat), FOREIGN KEY (DesignID) REFERENCES Parts_Designs (DesignID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (PartStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE);

CREATE TABLE Parts_Designs_TeamData (TeamID INTEGER NOT NULL,PartType INTEGER NOT NULL,NewDesignsThisSeason INTEGER NOT NULL,NewDesignsNextSeason INTEGER NOT NULL,PRIMARY KEY (TeamID,PartType),FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Parts_EnginePurchase_MonthlyPayments (TeamID INTEGER NOT NULL REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, EngineManufacturerID INTEGER REFERENCES Parts_Enum_EngineManufacturers (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, MonthsLeft INTEGER);

CREATE TABLE Parts_EngineerData (EngineerNum INTEGER PRIMARY KEY NOT NULL,SpeedIncrease decimal(5,2) NOT NULL);

CREATE TABLE Parts_Enum_CarStats (Value INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_DamageStates (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_DesignTypes (Value INTEGER UNIQUE PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_DevSpeeds (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,SpeedMultiplier decimal(4,2) NOT NULL,CostMultiplier decimal(4,2) NOT NULL,ExpertisePerDay decimal(4,2) NOT NULL);

CREATE TABLE Parts_Enum_EffectStrength (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_EmphasisPresets (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_EngineManufacturers (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,TeamID INTEGER NOT NULL,EngineDesignID INTEGER NOT NULL,ErsDesignID INTEGER NOT NULL,GearboxDesignID INTEGER NOT NULL,Cost INTEGER NOT NULL DEFAULT 0, StartOfSeasonUpfrontCost INTEGER NOT NULL DEFAULT 0, StartOfSeasonMonthlyCost INTEGER NOT NULL DEFAULT 0, StartOfSeasonMonthlyCostNumMonths INTEGER NOT NULL DEFAULT 0,FOREIGN KEY (ErsDesignID) REFERENCES Parts_Designs (DesignID) ON UPDATE CASCADE,FOREIGN KEY (GearboxDesignID) REFERENCES Parts_Designs (DesignID) ON UPDATE CASCADE,FOREIGN KEY (EngineDesignID) REFERENCES Parts_Designs (DesignID) ON UPDATE CASCADE,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON UPDATE CASCADE);

CREATE TABLE Parts_Enum_InspectionState (Value INTEGER NOT NULL PRIMARY KEY, Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_ProjectType (Value INTEGER UNIQUE PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_Stats (Value INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL);

CREATE TABLE Parts_Enum_Type (Value INTEGER UNIQUE PRIMARY KEY NOT NULL,Name TEXT NOT NULL,LocKey TEXT NOT NULL,BaseDesignCost INTEGER NOT NULL,BaseManufactureCost INTEGER NOT NULL,BaseDesignWork INTEGER NOT NULL,BaseManufactureWork INTEGER NOT NULL,PreSeasonDesignCostMultiplier decimal(3,2) NOT NULL DEFAULT 0.50,PreSeasonBuildCostMultiplier decimal(3,2) NOT NULL DEFAULT 0.50,PreSeasonQuantity int(3) NOT NULL DEFAULT 0,NegativeFocusMulOnSelf decimal(5,3) NOT NULL,NegativeFocusMulOnOthers decimal(5,3) NOT NULL,DamagePristineThreshold decimal(5,3) NOT NULL DEFAULT 1.000,DamageMinorThreshold decimal(5,3) NOT NULL DEFAULT 0.300,DamageMajorThreshold decimal(5,3) NOT NULL DEFAULT 0.100,DamageDestroyedThreshold decimal(5,3) NOT NULL DEFAULT 0.010);

CREATE TABLE Parts_InspectionResults(ItemID INTEGER NOT NULL, RaceID INTEGER REFERENCES Races(RaceID) ON DELETE CASCADE ON UPDATE RESTRICT, DesignID INTEGER NOT NULL REFERENCES Parts_Designs(DesignID) ON DELETE CASCADE ON UPDATE RESTRICT, LoadoutID INTEGER NOT NULL, ItemName TEXT NOT NULL, Result INTEGER NOT NULL REFERENCES Parts_Enum_InspectionState(Value) ON DELETE CASCADE ON UPDATE RESTRICT, PRIMARY KEY (ItemID, RaceID));

CREATE TABLE Parts_Items (ItemID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, DesignID INTEGER NOT NULL, BuildWork INTEGER NOT NULL DEFAULT 0, Condition decimal (7, 6) NOT NULL DEFAULT 1.0, ManufactureNumber INTEGER NOT NULL DEFAULT 0, ProjectID INTEGER DEFAULT NULL, AssociatedCar INTEGER DEFAULT NULL, InspectionState INTEGER NOT NULL REFERENCES Parts_Enum_InspectionState (Value) ON DELETE CASCADE ON UPDATE RESTRICT DEFAULT (0), LastEquippedCar INTEGER, FOREIGN KEY (DesignID) REFERENCES Parts_Designs (DesignID) ON DELETE CASCADE, FOREIGN KEY (ProjectID) REFERENCES Parts_Projects (ProjectID));

CREATE TABLE Parts_Items_Faults (ItemID INTEGER PRIMARY KEY NOT NULL REFERENCES Parts_Items (ItemID) ON DELETE CASCADE ON UPDATE RESTRICT, FaultType INTEGER NOT NULL, FaultName TEXT NOT NULL, FaultSeverity INTEGER NOT NULL);

CREATE TABLE Parts_NamingConventions (TeamID INTEGER PRIMARY KEY NOT NULL,Prefix TEXT NOT NULL,SeasonOffset INTEGER NOT NULL,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Parts_ParcFerme(    DesignID INTEGER NOT NULL REFERENCES Parts_Designs(DesignID) ON UPDATE RESTRICT ON DELETE CASCADE,    LoadoutID INTEGER NOT NULL,    TeamID INTEGER NOT NULL REFERENCES Teams(TeamID) ON UPDATE RESTRICT ON DELETE CASCADE,    PartType INTEGER NOT NULL REFERENCES Parts_Enum_Type(Value) ON UPDATE RESTRICT ON DELETE CASCADE, Session INTEGER NOT NULL DEFAULT 6, ItemID INTEGER DEFAULT 0 NOT NULL,    PRIMARY KEY(DesignID, LoadoutID));

CREATE TABLE Parts_PowertrainRaceHistoryData (TrackID INTEGER NOT NULL,TeamID INTEGER NOT NULL,AssociatedCar INTEGER NOT NULL,EnginePartsUsed INTEGER NOT NULL,ERSPartsUsed INTEGER NOT NULL,GearboxPartsUsed INTEGER NOT NULL,PRIMARY KEY (TrackID,TeamID,AssociatedCar),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE,FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID) ON DELETE CASCADE);

CREATE TABLE Parts_Projects (ProjectID INTEGER PRIMARY KEY NOT NULL,DesignID INTEGER NOT NULL,AssignmentID INTEGER NOT NULL,ManufactureSpeed INTEGER NOT NULL,Quantity INTEGER NOT NULL DEFAULT 0,Progress INTEGER NOT NULL DEFAULT 0,NewDesign INTEGER NOT NULL,StartDay INTEGER NOT NULL,FOREIGN KEY (AssignmentID) REFERENCES SubTeam_Assignments (AssignmentID),FOREIGN KEY (DesignID) REFERENCES Parts_Designs (DesignID) ON DELETE CASCADE,FOREIGN KEY (ManufactureSpeed) REFERENCES Parts_Enum_DevSpeeds (Value));

CREATE TABLE Parts_RecommendedTrackStats (TrackID INTEGER NOT NULL,CarStat INTEGER NOT NULL,IsCrucial INTEGER NOT NULL,PRIMARY KEY (TrackID,CarStat),FOREIGN KEY (CarStat) REFERENCES Parts_Enum_CarStats (Value) ON UPDATE CASCADE,FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID));

CREATE TABLE Parts_Resources (StandingPosition INTEGER PRIMARY KEY NOT NULL,WindTunnelBlocksRemaining INTEGER NOT NULL DEFAULT 0,CfdBlocksRemaining INTEGER NOT NULL DEFAULT 0);

CREATE TABLE Parts_StatDesignFocusModifiers (PartType INTEGER NOT NULL, SourceStat INTEGER NOT NULL, ImpactStat INTEGER NOT NULL, MinDesignFocusModifier decimal (3, 2) NOT NULL, MaxDesignFocusModifier decimal (3, 2) NOT NULL, PRIMARY KEY (PartType, SourceStat, ImpactStat), FOREIGN KEY (ImpactStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE, FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value), FOREIGN KEY (SourceStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE);

CREATE TABLE Parts_TeamExpertise (TeamID INTEGER NOT NULL DEFAULT 1, PartType INTEGER NOT NULL, PartStat INTEGER NOT NULL, Expertise decimal (8, 4) NOT NULL DEFAULT 0.0, NextSeasonExpertise decimal (8, 4) NOT NULL DEFAULT 0.0, SeasonStartExpertise decimal (8, 4) NOT NULL DEFAULT 0.0, PRIMARY KEY (PartType, PartStat, TeamID), FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value), FOREIGN KEY (PartStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Parts_TeamHistory (SeasonID INTEGER NOT NULL,TeamID INTEGER NOT NULL,EngineManufacturer INTEGER NOT NULL,PRIMARY KEY (SeasonID,TeamID),FOREIGN KEY (EngineManufacturer) REFERENCES Parts_Enum_EngineManufacturers (Value),FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Player (FirstName TEXT NOT NULL, LastName TEXT NOT NULL, TeamID INTEGER DEFAULT NULL, UniqueSeed INTEGER NOT NULL DEFAULT 0, FirstGameDay INTEGER, TeamPrincipalRating INTEGER, PreviousTeamPrincipalRating INTEGER, CustomTeamEnabled INTEGER NOT NULL DEFAULT 0, CustomTeamLogoBase64 TEXT, CustomTeamCarLiveryBase64 TEXT, PRIMARY KEY (FirstName, LastName), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Player_History(    TeamID INTEGER NOT NULL REFERENCES Teams(TeamID) ON UPDATE RESTRICT ON DELETE CASCADE,    StartDay INTEGER NOT NULL,    EndDay INTEGER,    PRIMARY KEY (TeamID, StartDay));

CREATE TABLE Player_PreSeason (SelectedEngineManufacturer INTEGER NOT NULL DEFAULT 1 PRIMARY KEY REFERENCES Parts_Enum_EngineManufacturers(Value));

CREATE TABLE Player_Record (StartSeason INTEGER NOT NULL PRIMARY KEY, FirstRace INTEGER DEFAULT NULL, FirstRaceTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstRaceTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, LastRace INTEGER DEFAULT NULL, LastRaceTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, LastRaceTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstWin INTEGER DEFAULT NULL, FirstWinTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstWinTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, LastWin INTEGER DEFAULT NULL, LastWinTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, LastWinTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstPodium INTEGER DEFAULT NULL, FirstPodiumTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstPodiumTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstPoints INTEGER DEFAULT NULL, FirstPointsTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FirstPointsTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, TotalDriverStarts INTEGER NOT NULL DEFAULT 0, TotalDriverFinishes INTEGER NOT NULL DEFAULT 0, BestQualifying INTEGER DEFAULT NULL, BestQualifyingYear INTEGER DEFAULT NULL, BestQualifyingTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, BestQualifyingTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, BestFinish INTEGER DEFAULT NULL, BestFinishYear INTEGER DEFAULT NULL, BestFinishTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, BestFinishTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, TotalDriverSprintWins INTEGER NOT NULL DEFAULT 0, TotalDriverPoles INTEGER NOT NULL DEFAULT 0, TotalDriverWins INTEGER NOT NULL DEFAULT 0, TotalDriverPodiums INTEGER NOT NULL DEFAULT 0, TotalDriverPointsScoringFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverPoints INTEGER NOT NULL DEFAULT 0, TotalDriverFastestLaps INTEGER NOT NULL DEFAULT 0, BestDriverChampionshipPlace INTEGER DEFAULT NULL, BestDriverChampionshipYear INTEGER DEFAULT NULL, BestDriverChampionshipTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, TotalDriverChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalDriverChampionshipPodiums INTEGER NOT NULL DEFAULT 0, BestConstructorChampionshipPlace INTEGER DEFAULT NULL, BestConstructorChampionshipYear INTEGER DEFAULT NULL, BestConstructorChampionshipTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, TotalConstructorChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalConstructorChampionshipPodiums INTEGER NOT NULL DEFAULT 0, TotalUniqueStarts INTEGER NOT NULL DEFAULT 0, TotalUniqueFinishes INTEGER NOT NULL DEFAULT 0, TotalUniquePodiums INTEGER NOT NULL DEFAULT 0, BestSprintFinish INTEGER DEFAULT NULL, BestSprintFinishYear INTEGER DEFAULT NULL, BestSprintFinishTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks (TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, BestSprintFinishTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, HighestTeamRating INTEGER DEFAULT NULL, HighestTeamRatingYear INTEGER DEFAULT NULL, HighestTeamRatingTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE, HighestAnnualIncome BIGINT (20) DEFAULT NULL, HighestAnnualIncomeYear INTEGER DEFAULT NULL, HighestAnnualIncomeTeamID INTEGER DEFAULT NULL REFERENCES Teams (TeamID) ON UPDATE RESTRICT ON DELETE CASCADE);

CREATE TABLE Player_State (Day INTEGER PRIMARY KEY NOT NULL DEFAULT 0,CurrentSeason INTEGER DEFAULT NULL,FOREIGN KEY (CurrentSeason) REFERENCES Seasons (SeasonID) ON DELETE NO ACTION ON UPDATE NO ACTION);

CREATE TABLE Races (RaceID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, SeasonID INTEGER NOT NULL, Day INTEGER NOT NULL, TrackID INTEGER NOT NULL, State INTEGER NOT NULL, RainPractice decimal (4, 3) NOT NULL, TemperaturePractice decimal (3, 1) NOT NULL, WeatherStatePractice INTEGER NOT NULL, RainQualifying decimal (4, 3) NOT NULL, TemperatureQualifying decimal (3, 1) NOT NULL, WeatherStateQualifying INTEGER NOT NULL, RainRace decimal (4, 3) NOT NULL, TemperatureRace decimal (3, 1) NOT NULL, WeatherStateRace INTEGER NOT NULL, WeekendType INTEGER REFERENCES Races_Enum_WeekendType (Type) DEFAULT (0) NOT NULL, FOREIGN KEY (State) REFERENCES Races_Enum_State (State), FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID));

CREATE TABLE Races_DriverStandings (SeasonID INTEGER NOT NULL, DriverID INTEGER NOT NULL, Points INTEGER NOT NULL, Position INTEGER NOT NULL, LastPointsChange INTEGER DEFAULT 0, LastPositionChange INTEGER DEFAULT 0, RaceFormula INTEGER DEFAULT (1) NOT NULL, PRIMARY KEY (SeasonID, DriverID, RaceFormula), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE);

CREATE TABLE Races_Enum_PenaltyType (Type INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,GridPenalty INTEGER NOT NULL,FirstOffenceModifier INTEGER NOT NULL DEFAULT 1);

CREATE TABLE Races_Enum_State (State INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Races_Enum_TrackType (Value INTEGER PRIMARY KEY NOT NULL, Name STRING NOT NULL);

CREATE TABLE Races_Enum_WeekendType (Type INTEGER NOT NULL PRIMARY KEY, Name TEXT NOT NULL);

CREATE TABLE Races_FeatureRaceResults (SeasonID INT, RaceID INT, FinishingPos INT, DriverID INT, TeamID INT, FastestLap NUM, LapCount INT, TimeDeltaFromLead NUM, AverageLap NUM, RaceScore NUM, RaceTime NUM, IncidentSeverity INT, RaceFormula INT, PitStopTime DECIMAL (5, 2), ChampionshipPoints INTEGER DEFAULT (0), Performance INTEGER NOT NULL DEFAULT (2) REFERENCES Staff_Enum_DriverSessionPerformance (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, PRIMARY KEY (SeasonID, RaceID, FinishingPos, RaceFormula));

CREATE TABLE "Races_FeederSeries_RaceLength" (
	"TrackID"	INTEGER NOT NULL,
	"RaceFormula"	INTEGER NOT NULL,
	"SprintLength"	INTEGER NOT NULL,
	"FeatureLength"	INTEGER NOT NULL,
	FOREIGN KEY("TrackID") REFERENCES "Races_Tracks"("TrackID"),
	PRIMARY KEY("TrackID","RaceFormula")
);

CREATE TABLE Races_GridPenalties (PenaltyID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, TeamID INTEGER NOT NULL, CarID INTEGER NOT NULL, ReasonForPenalty INTEGER NOT NULL, SessionReceived INTEGER NOT NULL, Served INTEGER NOT NULL DEFAULT 0, PitLaneStart INTEGER NOT NULL, ServeInRace INTEGER NOT NULL DEFAULT 1, ServeInSprint INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (ReasonForPenalty) REFERENCES Races_Enum_PenaltyType (Type) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE);

CREATE TABLE Races_PitCrewStandings (SeasonID INTEGER NOT NULL, TeamID INTEGER NOT NULL, Points INTEGER NOT NULL, Position INTEGER NOT NULL, LastPointsChange INTEGER DEFAULT (0) NOT NULL, LastPositionChange INTEGER DEFAULT (0) NOT NULL, RaceFormula INTEGER NOT NULL, PRIMARY KEY (SeasonID, TeamID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Races_PitStopResults (SeasonID INTEGER NOT NULL, RaceID INTEGER NOT NULL, TeamID INTEGER NOT NULL, FinishPosition INTEGER NOT NULL, FastestPitStopID INTEGER NOT NULL, FastestPitStopTime DECIMAL (6, 3) NOT NULL, DriverID INTEGER NOT NULL, Points INTEGER DEFAULT (0) NOT NULL, PRIMARY KEY (SeasonID, RaceID, TeamID, FinishPosition), FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Races_PitStopTimings (SeasonID INTEGER NOT NULL, RaceID INTEGER NOT NULL, TeamID INTEGER NOT NULL, DriverID INTEGER NOT NULL, PitStopID INTEGER NOT NULL, PitStopStage INTEGER NOT NULL, Duration DECIMAL (6, 3) NOT NULL, IncidentDelay DECIMAL (6, 3) DEFAULT (0.0) NOT NULL, Lap INTEGER NOT NULL DEFAULT (0), PRIMARY KEY (SeasonID, RaceID, TeamID, DriverID, PitStopID, PitStopStage), FOREIGN KEY (PitStopStage) REFERENCES Staff_Enum_PitStopStage (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Races_PracticeResults (SeasonID INTEGER NOT NULL, RaceID INTEGER NOT NULL, PracticeSession INTEGER NOT NULL, DriverID INTEGER NOT NULL, TeamID INTEGER NOT NULL, TimeOnTrack decimal (8, 2) NOT NULL, SessionDuration decimal (8, 2) NOT NULL, BestLapTime decimal (7, 3) NOT NULL, BestLapTyre INTEGER NOT NULL, LapCount INTEGER NOT NULL, GridPenalty INTEGER NOT NULL, RaceFormula INTEGER DEFAULT (1), PRIMARY KEY (SeasonID, RaceID, PracticeSession, DriverID, RaceFormula), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Races_QualifyingResults (SeasonID INTEGER NOT NULL, RaceID INTEGER NOT NULL, QualifyingStage INTEGER NOT NULL, SprintShootout INTEGER NOT NULL, FinishingPos INTEGER NOT NULL, DriverID INTEGER NOT NULL, TeamID INTEGER NOT NULL, FastestLap decimal (5, 2) NOT NULL, DNF INTEGER NOT NULL, LapCount INTEGER DEFAULT 0, GridPenalty INTEGER NOT NULL, RaceFormula INTEGER DEFAULT (1), ChampionshipPoints INTEGER DEFAULT (0), PRIMARY KEY (SeasonID, RaceID, QualifyingStage, SprintShootout, FinishingPos, RaceFormula), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Races_Results (Season INTEGER NOT NULL, RaceID INTEGER NOT NULL, FinishingPos INTEGER NOT NULL, DriverID INTEGER NOT NULL, TeamID INTEGER NOT NULL, Laps INTEGER NOT NULL, Time decimal (8, 3) NOT NULL, FastestLap decimal (8, 3) NOT NULL, Points INTEGER NOT NULL, DNF INTEGER NOT NULL, SuccessfulOvertakes INTEGER NOT NULL, FailedOvertakes INTEGER NOT NULL, SuccessfulDefends INTEGER NOT NULL, FailedDefends INTEGER NOT NULL, SafetyCarDeployments INTEGER NOT NULL, VirtualSafetyCarDeployments INTEGER NOT NULL DEFAULT 0, StartingPos INTEGER NOT NULL, FuelUsed decimal (10, 4) NOT NULL DEFAULT 0.0, Performance INTEGER REFERENCES Staff_Enum_DriverSessionPerformance (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL DEFAULT (2), PRIMARY KEY (Season, RaceID, FinishingPos), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE, FOREIGN KEY (Season) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Races_SprintResults (SeasonID INTEGER NOT NULL, RaceID INTEGER NOT NULL, FinishingPos INTEGER NOT NULL, DriverID INTEGER NOT NULL, TeamID INTEGER NOT NULL, FastestLap DECIMAL (5, 2) NOT NULL, DNF INTEGER NOT NULL, LapCount INTEGER NOT NULL, TimeDeltaFromLead DECIMAL (5, 2) NOT NULL, GridPenalty INTEGER NOT NULL, AverageLap INTEGER, RaceScore INTEGER, RaceTime DECIMAL (5, 2) NOT NULL, IncidentSeverity INTEGER, RaceFormula INTEGER DEFAULT (1), ChampionshipPoints INTEGER DEFAULT (0), Performance INTEGER REFERENCES Staff_Enum_DriverSessionPerformance (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL DEFAULT (2), PRIMARY KEY (SeasonID, RaceID, FinishingPos, RaceFormula), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Races_Strategies (StrategyID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,DriverID INTEGER NOT NULL,StintID INTEGER NOT NULL,TrackID INTEGER NOT NULL,SeasonID INTEGER NOT NULL,StartingLap INTEGER NOT NULL,EndingLap INTEGER NOT NULL,TyreSet INTEGER NOT NULL,PitLap INTEGER NOT NULL,PitWindowStart INTEGER NOT NULL,PitWindowOptimal INTEGER NOT NULL,PitWindowEnd INTEGER NOT NULL,FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE NO ACTION,FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE NO ACTION,FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID) ON DELETE CASCADE ON UPDATE NO ACTION);

CREATE TABLE Races_TeamPerformance (SeasonID INTEGER NOT NULL,TeamID INTEGER NOT NULL,TrackID INTEGER NOT NULL,Straights float NOT NULL,SlowCorners float NOT NULL,MediumCorners float NOT NULL,FastCorners float NOT NULL,PRIMARY KEY (SeasonID,TeamID,TrackID),FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE NO ACTION,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE NO ACTION,FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID) ON DELETE CASCADE ON UPDATE NO ACTION);

CREATE TABLE Races_TeamStandings (SeasonID INTEGER NOT NULL,TeamID INTEGER NOT NULL,Points INTEGER NOT NULL,Position INTEGER NOT NULL,LastPointsChange INTEGER DEFAULT 0,LastPositionChange INTEGER DEFAULT 0, "RaceFormula" INTEGER DEFAULT (1),PRIMARY KEY (TeamID,SeasonID),FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Races_Templates (TrackID INTEGER PRIMARY KEY NOT NULL, RainMin decimal (4, 3) NOT NULL, RainMax decimal (4, 3) NOT NULL, TemperatureMin decimal (3, 1) NOT NULL, TemperatureMax decimal (3, 1) NOT NULL, WeekOfYear INTEGER NOT NULL, TemperatureSkew decimal (4, 3) NOT NULL, WeekendType INTEGER REFERENCES Races_Enum_WeekendType (Type) ON DELETE RESTRICT ON UPDATE RESTRICT NOT NULL, StartingWeekDay NOT NULL DEFAULT 4, Disabled INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (TrackID) REFERENCES Races_Tracks (TrackID));

CREATE TABLE Races_Tracks (TrackID INTEGER UNIQUE PRIMARY KEY NOT NULL, Name TEXT NOT NULL, CountryID INTEGER REFERENCES Countries (CountryID) ON DELETE RESTRICT ON UPDATE RESTRICT NOT NULL, Laps INTEGER NOT NULL, FirstRace bigint (20) NOT NULL, ProfileText mediumtext NOT NULL, TrackLength decimal (8, 3) NOT NULL, TypeOfTrack INTEGER NOT NULL, FastestLap decimal (8, 3) NOT NULL, FastestLapDriverID INTEGER NOT NULL, LastWinner INTEGER NOT NULL, LastPolePosition INTEGER NOT NULL, MostWins INTEGER NOT NULL, FastestLapYear INTEGER NOT NULL, SafetyCarChance decimal (8, 2) NOT NULL DEFAULT 0.0, PitLaneTimeLoss INTEGER NOT NULL DEFAULT 0, GreenFlagTimeLoss INTEGER NOT NULL DEFAULT 0, SafetyCarTimeLoss INTEGER NOT NULL DEFAULT 0, StartFinishLineOffset decimal (8, 3) NOT NULL DEFAULT 0.0, SprintLaps INTEGER DEFAULT (20) NOT NULL, IsF2Race INTEGER NOT NULL DEFAULT (0), IsF3Race INTEGER NOT NULL DEFAULT (0), FOREIGN KEY (FastestLapDriverID) REFERENCES Staff_DriverData (StaffID), FOREIGN KEY (TypeOfTrack) REFERENCES Races_Enum_TrackType (Value) ON DELETE RESTRICT ON UPDATE RESTRICT);

CREATE TABLE Regulations_ChangeGroups (GroupID INTEGER PRIMARY KEY NOT NULL, ChangeType INTEGER NOT NULL, LocKey TEXT NOT NULL, FOREIGN KEY (ChangeType) REFERENCES Regulations_Enum_ChangeType (Value));

CREATE TABLE Regulations_ChangeGroups_VotingPairs (VotePairID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,ChangeGroup1 INTEGER NOT NULL,ChangeGroup2 INTEGER DEFAULT NULL,DescriptionLocKey TEXT NOT NULL,FOREIGN KEY (ChangeGroup1) REFERENCES Regulations_ChangeGroups (GroupID),FOREIGN KEY (ChangeGroup2) REFERENCES Regulations_ChangeGroups (GroupID));

CREATE TABLE Regulations_Enum_ChangeType (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL,LocKey TEXT NOT NULL,DescriptionLocKey TEXT NOT NULL,GroupSeasonDelay INTEGER NOT NULL DEFAULT 1,SkipSeasonProbability decimal(3,2) NOT NULL DEFAULT 0.00);

CREATE TABLE Regulations_Enum_Changes (ChangeID INTEGER PRIMARY KEY NOT NULL, Name TEXT NOT NULL, ChangeType INTEGER NOT NULL, CurrentValue bigint (20) NOT NULL, PreviousValue INTEGER NOT NULL DEFAULT 0, MinValue bigint (20) NOT NULL, MaxValue bigint (20) NOT NULL, LocKey TEXT NOT NULL, DescriptionLocKey TEXT NOT NULL, FOREIGN KEY (ChangeType) REFERENCES Regulations_Enum_ChangeType (Value));

CREATE TABLE Regulations_Enum_State (Value INTEGER PRIMARY KEY NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Regulations_EventCalendar (Month INTEGER NOT NULL,ChangeType INTEGER NOT NULL,SeasonDelta INTEGER NOT NULL,PRIMARY KEY (Month,ChangeType),FOREIGN KEY (ChangeType) REFERENCES Regulations_Enum_ChangeType (Value));

CREATE TABLE Regulations_NonTechnical (GroupID INTEGER NOT NULL,Regulation INTEGER NOT NULL,Value INTEGER NOT NULL,PRIMARY KEY (GroupID,Regulation),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID),FOREIGN KEY (Regulation) REFERENCES Regulations_Enum_Changes (ChangeID) ON UPDATE CASCADE);

CREATE TABLE Regulations_NonTechnical_PartResources (ResourcePackage INTEGER NOT NULL,StandingPos INTEGER NOT NULL,WindTunnelBlocks INTEGER NOT NULL,CfdBlocks INTEGER NOT NULL,PRIMARY KEY (ResourcePackage,StandingPos));

CREATE TABLE Regulations_NonTechnical_PointSchemes (PointScheme INTEGER NOT NULL,RacePos INTEGER NOT NULL,Points INTEGER NOT NULL,PRIMARY KEY (PointScheme,RacePos));

CREATE TABLE Regulations_NonTechnical_PrizeShare (DistributionSystem INTEGER NOT NULL,FinishPosition INTEGER NOT NULL,PrizeShare decimal(4,3) NOT NULL,PRIMARY KEY (DistributionSystem,FinishPosition));

CREATE TABLE Regulations_Proposals (ProposalID INTEGER PRIMARY KEY NOT NULL,ChangeType INTEGER NOT NULL,VoteDay INTEGER NOT NULL,TargetSeason INTEGER NOT NULL,FOREIGN KEY (ChangeType) REFERENCES Regulations_Enum_ChangeType (Value));

CREATE TABLE Regulations_Proposals_ChangeGroups (ProposalID INTEGER NOT NULL,GroupID INTEGER NOT NULL,State INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (ProposalID,GroupID),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID),FOREIGN KEY (ProposalID) REFERENCES Regulations_Proposals (ProposalID) ON DELETE CASCADE);

CREATE TABLE Regulations_TeamVotes (ProposalID INTEGER NOT NULL,TeamID INTEGER NOT NULL,GroupID INTEGER NOT NULL,PRIMARY KEY (ProposalID,TeamID),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID),FOREIGN KEY (ProposalID) REFERENCES Regulations_Proposals (ProposalID) ON DELETE CASCADE,FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Regulations_Technical_StatReductions (GroupID INTEGER NOT NULL,PartStat INTEGER NOT NULL,StatReduction decimal(3,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (GroupID,PartStat),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (PartStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE);

CREATE TABLE Regulations_Technical_SweepingReductions (GroupID INTEGER PRIMARY KEY NOT NULL,SweepingReduction decimal(3,2) NOT NULL DEFAULT 0.00,FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID));

CREATE TABLE Regulations_Technical_TypeReductions (GroupID INTEGER NOT NULL,PartType INTEGER NOT NULL,TypeReduction decimal(3,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (GroupID,PartType),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value));

CREATE TABLE Regulations_Technical_TypeStatComboReductions (GroupID INTEGER NOT NULL,PartType INTEGER NOT NULL,PartStat INTEGER NOT NULL,ComboReduction decimal(3,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (GroupID,PartType,PartStat),FOREIGN KEY (GroupID) REFERENCES Regulations_ChangeGroups (GroupID),FOREIGN KEY (PartStat) REFERENCES Parts_Enum_Stats (Value) ON UPDATE CASCADE,FOREIGN KEY (PartType) REFERENCES Parts_Enum_Type (Value));

CREATE TABLE Save_CarAI (CarIndex INTEGER PRIMARY KEY NOT NULL UNIQUE, RiskLevel INTEGER NOT NULL, ControlType INTEGER NOT NULL, Approach INTEGER NOT NULL);

CREATE TABLE Save_CarAI_Practice (CarID INTEGER PRIMARY KEY UNIQUE NOT NULL, State INTEGER NOT NULL, NextRunTimeSelected INTEGER NOT NULL, RunCount INTEGER NOT NULL, CurrentRunTargetLaps INTEGER NOT NULL, LapCountAtRunStart INTEGER NOT NULL, FreshTyresToUse INTEGER NOT NULL, NextRunTime DECIMAL (6, 3) NOT NULL, CurrentRunTargetTime DECIMAL (6, 3) NOT NULL, CurrentRunStartTime DECIMAL (6, 3) NOT NULL, AllowedTyreBitField INTEGER NOT NULL);

CREATE TABLE Save_CarAI_Qualifying (CarID INTEGER PRIMARY KEY UNIQUE NOT NULL, State INTEGER NOT NULL, NextRunPrioritiseFreshTyres INTEGER NOT NULL, LastRunAborted INTEGER NOT NULL, WillSkipFinalRun INTEGER NOT NULL, RunCount INTEGER NOT NULL, FullRunDuration DECIMAL (6, 3) NOT NULL, LastRunCutOff DECIMAL (6, 3) NOT NULL, WorstConditionsLastRun DECIMAL (6, 3) NOT NULL, QualifyingCutoffSafetyThreshold DECIMAL (6, 3) NOT NULL, RunWeatherLookahead DECIMAL (6, 3) NOT NULL);

CREATE TABLE Save_CarAI_Race (CarID INTEGER PRIMARY KEY UNIQUE NOT NULL, RedFlagActive INTEGER NOT NULL, SafetyCarActive INTEGER NOT NULL, VirtualSafetyCarActive INTEGER NOT NULL, ChargingERS INTEGER NOT NULL, BattleState INTEGER NOT NULL, ConfidenceState INTEGER NOT NULL, LastUpdatedPitstopStrategy INTEGER NOT NULL, LastUpdatedFuelDelta DECIMAL (6, 3) NOT NULL, LastTriggeredLowFuelEvent DECIMAL (6, 3) NOT NULL, LastUpdatedCommands DECIMAL (6, 3) NOT NULL, LastUpdatedWeatherReport DECIMAL (6, 3) NOT NULL, WeatherReportMagnitudeDistortion DECIMAL (6, 3) NOT NULL);

CREATE TABLE Save_CarAI_Race_Stints (CarID INTEGER NOT NULL, TyreID INTEGER NOT NULL, StartingLap INTEGER NOT NULL);

