CREATE TABLE Save_Strategist_QualificationRun (    TeamID                INTEGER        NOT NULL,    LoadoutID             INTEGER        NOT NULL,    RunStartTime          DECIMAL (6, 3) NOT NULL,	RunEstimatedEndTime   DECIMAL (6, 3) NOT NULL,	TyreSetID             INTEGER        NOT NULL,	FastLapCount          INTEGER        NOT NULL,	CurrentState          INTEGER        NOT NULL,	IncludeCooldownLaps   BOOLEAN        NOT NULL,	AdditionalLapsOfFuel  INTEGER        NOT NULL,	CurrentRun            BOOLEAN        NOT NULL,    PRIMARY KEY (        TeamID,        LoadoutID    ),    FOREIGN KEY (        TeamID    )    REFERENCES Teams (TeamID) );

