CREATE TABLE Save_TimingManager_TrackCheckpoints (CarIndex INTEGER NOT NULL, Checkpoint INTEGER NOT NULL, RaceTime DECIMAL (6, 3) NOT NULL);

CREATE TABLE Save_WeatherHistory (Time INTEGER PRIMARY KEY NOT NULL, Rain DECIMAL (6, 3) NOT NULL, WaterOnTrack DECIMAL (6, 3) NOT NULL, AmbientTemperature DECIMAL (6, 3) NOT NULL, TrackTemperature DECIMAL (6, 3) NOT NULL, WeatherState INTEGER NOT NULL, TimeUntilTrackDry DECIMAL (6, 3) NOT NULL, RubberOnTrack DECIMAL (6, 3) NOT NULL);

CREATE TABLE Save_Weekend (ID INTEGER PRIMARY KEY NOT NULL, RaceID INTEGER NOT NULL, WeekendStage INTEGER NOT NULL, CurrentGuiScreen INTEGER NOT NULL, ActiveStepID INTEGER NOT NULL, CurrentStageInnerStep INTEGER NOT NULL, PreviousStageInnerStep INTEGER NOT NULL, TrackRubber decimal (6, 3) NOT NULL, SimulatedP1 INTEGER NOT NULL, SimulatedP2 INTEGER NOT NULL, SimulatedP3 INTEGER NOT NULL, SimulatedQ1 INTEGER NOT NULL, SimulatedQ2 INTEGER NOT NULL, SimulatedQ3 INTEGER NOT NULL, MidSessionSave BOOLEAN NOT NULL DEFAULT 0, TimeRemaining DECIMAL (6, 3) NOT NULL, CurrentLap INTEGER NOT NULL, LapCount INTEGER NOT NULL, SessionSkippedTime DECIMAL (6, 3) NOT NULL, SessionDelayTime DECIMAL (6, 3) NOT NULL, SimulatedSQ1 INTEGER NOT NULL, SimulatedSQ2 INTEGER NOT NULL, SimulatedSQ3 INTEGER NOT NULL, SimulatedSprint INTEGER NOT NULL, SimulatedRace INTEGER NOT NULL, FOREIGN KEY (RaceID) REFERENCES Races (RaceID) ON DELETE CASCADE ON UPDATE NO ACTION);

CREATE TABLE Scenario_Config (ScenarioID INTEGER NOT NULL PRIMARY KEY, ScenarioType INTEGER NOT NULL, ScenarioDLCID TEXT (64) NOT NULL DEFAULT (''), ScenarioCategory TEXT (64) NOT NULL DEFAULT (''), DifficultyRating INTEGER NOT NULL DEFAULT (2));

CREATE TABLE Scenario_Objectives (ID INTEGER PRIMARY KEY UNIQUE NOT NULL, Title TEXT NOT NULL, Blurb TEXT NOT NULL, ObjectiveType INTEGER NOT NULL, ObjectiveTarget INTEGER NOT NULL, ObjectiveValue INTEGER NOT NULL);

CREATE TABLE Scenario_RealFinishPositions (CarID INTEGER PRIMARY KEY UNIQUE NOT NULL, FinishPosition INTEGER UNIQUE NOT NULL, Points INTEGER NOT NULL, Pitstops INTEGER NOT NULL, IsDNF INTEGER NOT NULL, HasFastestLap INTEGER NOT NULL);

CREATE TABLE Scenario_SeasonData (TeamID INTEGER PRIMARY KEY UNIQUE NOT NULL, Wins INTEGER NOT NULL, Podiums INTEGER NOT NULL, FastestLaps NOT NULL, PolePositions NOT NULL, RacesFinished NOT NULL, RacesTotal NOT NULL);

CREATE TABLE Scenario_WeatherOverride (Day INTEGER PRIMARY KEY UNIQUE NOT NULL, AmbientTempHigh DECIMAL (6, 3) NOT NULL, AmbientTempLow DECIMAL (6, 3) NOT NULL, AmbientTempSkew DECIMAL (6, 3) NOT NULL, TrackTempHigh DECIMAL (6, 3) NOT NULL, TrackTempLow DECIMAL (6, 3) NOT NULL, TrackTempSkew DECIMAL (6, 3) NOT NULL);

CREATE TABLE Scenario_WeatherOverride_States (StateIndex INTEGER PRIMARY KEY UNIQUE NOT NULL, StateType INTEGER NOT NULL, Rain DECIMAL (6, 3) NOT NULL);

CREATE TABLE Scouting (TeamID INTEGER NOT NULL, StaffID INTEGER NOT NULL, AssignmentID INTEGER DEFAULT NULL, ScoutType INTEGER DEFAULT NULL, StartDay INTEGER DEFAULT NULL, WorkLeft decimal (10, 5) DEFAULT NULL, Accuracy INTEGER DEFAULT NULL, LastScoutedType INTEGER DEFAULT NULL, LastScoutedEndDay INTEGER DEFAULT NULL, LastScoutedAccuracy INTEGER DEFAULT NULL, LastScoutedDaysUtilExpired INTEGER DEFAULT (0), PRIMARY KEY (TeamID, StaffID), FOREIGN KEY (ScoutType) REFERENCES Scouting_Enum_ScoutType (Value), FOREIGN KEY (AssignmentID) REFERENCES SubTeam_Assignments (AssignmentID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Scouting_Enum_ScoutType (Value INTEGER UNIQUE PRIMARY KEY NOT NULL,Name TEXT NOT NULL,Cost bigint(20) NOT NULL,ScoutLength INTEGER NOT NULL,ScoutingAccuracy INTEGER NOT NULL);

CREATE TABLE Scouting_Staff_Bonuses (StaffID INTEGER PRIMARY KEY NOT NULL, TeamID INTEGER NOT NULL, DayScouted INTEGER NOT NULL, StartingBonus INTEGER NOT NULL, RaceBonus INTEGER NOT NULL, RaceBonusTargetPos INTEGER NOT NULL, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Scouting_Staff_Bookmark (    TeamID  INTEGER NOT NULL,    StaffID INTEGER NOT NULL,    FOREIGN KEY (        TeamID    )    REFERENCES Teams (TeamID) ON DELETE CASCADE                              ON UPDATE RESTRICT,    FOREIGN KEY (        StaffID    )    REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE                                        ON UPDATE RESTRICT,    PRIMARY KEY (        TeamID,        StaffID    ));

CREATE TABLE Scouting_Staff_CommonData (StaffID INTEGER NOT NULL DEFAULT 0, AnnualSalary bigint (20) NOT NULL DEFAULT 0, TeamID INTEGER NOT NULL, DayScouted INTEGER NOT NULL, Mentality INTEGER NOT NULL DEFAULT (0), TeamSuitability INTEGER NOT NULL DEFAULT (0), TeamOpinion INTEGER NOT NULL DEFAULT (0), PRIMARY KEY (StaffID, TeamID), FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Scouting_Staff_DriverRivalryEventLogs (DriverID INTEGER PRIMARY KEY NOT NULL,RivalryEventType INTEGER NOT NULL,RivalID INTEGER NOT NULL,RivalryPoints decimal(6,2) NOT NULL,TeamID INTEGER NOT NULL,DayScouted INTEGER NOT NULL,FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (RivalID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (RivalryEventType) REFERENCES Staff_Enum_RivalryEventTypes (Value));

CREATE TABLE Scouting_Staff_PerformanceStats (StaffID INTEGER NOT NULL, StatID INTEGER NOT NULL, Val INTEGER NOT NULL DEFAULT 50, Max INTEGER NOT NULL DEFAULT 80, TeamID INTEGER NOT NULL, DayScouted INTEGER NOT NULL, AccuracyOffset INTEGER NOT NULL, PRIMARY KEY (StaffID, StatID, TeamID), FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (StatID) REFERENCES Staff_Enum_PerformanceStatTypes (Value), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Scouting_Staff_RaceEngineerDriverAssignments (RaceEngineerID INTEGER PRIMARY KEY NOT NULL, DriverID INTEGER NOT NULL, RelationshipLevel decimal (8, 3) NOT NULL, TeamID INTEGER NOT NULL, DayScouted INTEGER NOT NULL, FOREIGN KEY (DriverID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (RaceEngineerID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE Scouting_Staff_Traits (StaffID INTEGER NOT NULL, TraitID INTEGER NOT NULL, TeamID INTEGER NOT NULL, DayScouted INTEGER NOT NULL, PRIMARY KEY (StaffID, TraitID, TeamID), FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID), FOREIGN KEY (TraitID) REFERENCES Staff_Traits_Definitions (TraitID));

CREATE TABLE Seasons (SeasonID INTEGER PRIMARY KEY NOT NULL,PrizePool bigint(20) NOT NULL DEFAULT 500000000,EntryBaseFee bigint(20) NOT NULL DEFAULT 556509,EntryPerPointFirst bigint(20) NOT NULL DEFAULT 6677,EntryPerPointOther bigint(20) NOT NULL DEFAULT 5563);

CREATE TABLE Seasons_Deadlines (SeasonID INTEGER NOT NULL,DeadlineType INTEGER NOT NULL,Day INTEGER NOT NULL,PRIMARY KEY (SeasonID,DeadlineType,Day),FOREIGN KEY (DeadlineType) REFERENCES Seasons_Enum_DeadlineType (DeadlineType),FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE);

