CREATE TABLE Sponsorship_RaceBonuses (DriverID INTEGER NOT NULL REFERENCES Staff_DriverData (StaffID) ON UPDATE RESTRICT ON DELETE CASCADE, RaceID INTEGER NOT NULL REFERENCES Races (RaceID) ON UPDATE RESTRICT ON DELETE CASCADE, Difficulty INTEGER NOT NULL REFERENCES Sponsorship_Enum_RaceBonusDifficulty (Value) ON UPDATE RESTRICT ON DELETE CASCADE, Position INTEGER NOT NULL, Selected INTEGER NOT NULL DEFAULT 0, Achieved INTEGER NOT NULL DEFAULT (0), PRIMARY KEY (DriverID, RaceID, Difficulty));

CREATE TABLE Staff_BasicData (StaffID INTEGER PRIMARY KEY NOT NULL UNIQUE, FirstName TEXT NOT NULL DEFAULT ('FIRST_NAME'), LastName TEXT NOT NULL DEFAULT ('LAST_NAME'), CountryID INTEGER NOT NULL DEFAULT (1) REFERENCES Countries (CountryID) ON DELETE RESTRICT ON UPDATE RESTRICT, DOB INTEGER DEFAULT (0) NOT NULL, DOB_ISO DATE DEFAULT ('1970-01-01'), Gender INTEGER NOT NULL DEFAULT (0), IsGeneratedStaff INTEGER NOT NULL DEFAULT (1), PhotoDay INTEGER, FaceType INTEGER, FaceIndex INTEGER, AgeType INTEGER, IsGeneratedForCustomTeam INTEGER NOT NULL DEFAULT (0), FOREIGN KEY (Gender) REFERENCES Staff_Enum_Gender (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

