CREATE TABLE Staff_ContractOffers (StaffID INTEGER NOT NULL, OfferType INTEGER NOT NULL DEFAULT (0), ContractState INTEGER NOT NULL DEFAULT 1, OfferDay INTEGER NOT NULL DEFAULT 0, PatienceWhenOffered DECIMAL (3, 2) NOT NULL DEFAULT 1.0, TeamID INTEGER NOT NULL, PosInTeam INTEGER NOT NULL, PosInTeamOpinionScore decimal (3, 2) DEFAULT (0.5) NOT NULL, PosInTeamOpinion INTEGER NOT NULL DEFAULT 1, PosInTeamOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', StartDay INTEGER NOT NULL DEFAULT 43831, EndSeason INTEGER NOT NULL DEFAULT 2022, LengthOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), LengthOpinion INTEGER NOT NULL DEFAULT 1, LengthOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', Salary INTEGER NOT NULL DEFAULT 100000, SalaryOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), SalaryOpinion INTEGER NOT NULL DEFAULT 1, SalaryOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', StartingBonus INTEGER NOT NULL DEFAULT 0, StartingBonusOpinionScore decimal (3, 2) DEFAULT (0.5) NOT NULL, StartingBonusOpinion INTEGER NOT NULL DEFAULT 1, StartingBonusOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', RaceBonus INTEGER NOT NULL DEFAULT 0, RaceBonusOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), RaceBonusOpinion INTEGER NOT NULL DEFAULT 1, RaceBonusOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', RaceBonusTargetPos INTEGER NOT NULL DEFAULT 1, RaceBonusTargetPosOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), RaceBonusTargetPosOpinion INTEGER NOT NULL DEFAULT 1, RaceBonusTargetPosOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', BreakoutClause DECIMAL (3, 2) NOT NULL DEFAULT (0), BreakoutClauseOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), BreakoutClauseOpinion INTEGER NOT NULL DEFAULT (1), BreakoutClauseOpinionStr TEXT DEFAULT OPINION_STRING_NEUTRAL NOT NULL, StartDateType INTEGER REFERENCES Staff_Enum_ContractStartDateType (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL DEFAULT (0), StartDateTypeOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), StartDateTypeOpinion INTEGER REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL DEFAULT (1), StartDateTypeOpinionStr TEXT NOT NULL DEFAULT '[OPINION_STRING_NEUTRAL]', AffiliateAgeOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), AffiliateAgeOpinion INTEGER DEFAULT (1) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, AffiliateAgeOpinionStr TEXT NOT NULL DEFAULT OPINION_STRING_NEUTRAL, AffiliateCountOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), AffiliateCountOpinion INTEGER REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT DEFAULT (1), AffiliateCountOpinionStr TEXT NOT NULL DEFAULT OPINION_STRING_NEUTRAL, AffiliatePendingF1RacePosOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), AffiliatePendingF1RacePosOpinion INTEGER REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT DEFAULT (1), AffiliatePendingF1RacePosOpinionStr TEXT NOT NULL DEFAULT OPINION_STRING_NEUTRAL, AffiliateDualRoleClause INTEGER NOT NULL DEFAULT (0), AffiliateDualRoleClauseOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), AffiliateDualRoleClauseOpinion INTEGER NOT NULL DEFAULT (1) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, AffiliateDualRoleClauseOpinionStr TEXT NOT NULL DEFAULT OPINION_STRING_NEUTRAL, ExpirationDay INTEGER DEFAULT (- 1) NOT NULL, OfferDeadlineOpinionScore decimal (3, 2) NOT NULL DEFAULT (0.5), OfferDeadlineOpinion INTEGER NOT NULL DEFAULT (1) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, OfferDeadlineOpinionStr TEXT NOT NULL DEFAULT OPINION_STRING_NEUTRAL, EstimatedResponseDay INTEGER DEFAULT (- 1) NOT NULL, SatisfactionScore DECIMAL (3, 2) DEFAULT (- 1) NOT NULL, PRIMARY KEY (StaffID, OfferType, TeamID), FOREIGN KEY (LengthOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (PosInTeamOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (RaceBonusOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (RaceBonusTargetPosOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SalaryOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (StartingBonusOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (ContractState) REFERENCES Staff_Enum_ContractState (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (OfferType) REFERENCES Staff_Enum_ContractOfferType (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (BreakoutClauseOpinion) REFERENCES Staff_Enum_Opinions (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

