CREATE TABLE Staff_Contracts (StaffID INTEGER NOT NULL, ContractType INTEGER NOT NULL DEFAULT 0, TeamID INTEGER NOT NULL, PosInTeam INTEGER NOT NULL, StartDay INTEGER NOT NULL DEFAULT 43831, EndSeason INTEGER NOT NULL DEFAULT 2022, Salary INTEGER NOT NULL DEFAULT 100000, StartingBonus INTEGER NOT NULL DEFAULT 0, RaceBonus INTEGER NOT NULL DEFAULT 0, RaceBonusTargetPos INTEGER NOT NULL DEFAULT 1, BreakoutClause decimal (3, 2) DEFAULT (0.5) NOT NULL, AffiliateDualRoleClause INTEGER NOT NULL DEFAULT (0), PRIMARY KEY (StaffID, ContractType, TeamID), FOREIGN KEY (ContractType) REFERENCES Staff_Enum_ContractType (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

