ces_Tracks (TrackID), FOREIGN KEY (LastWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (StaffID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY (StaffID, Formula));

