CREATE TABLE Staff_Mentality_AreaOpinions (StaffID INTEGER NOT NULL REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, Category INTEGER NOT NULL REFERENCES Staff_Enum_MentalityCategory (Value) ON UPDATE RESTRICT ON DELETE CASCADE, Opinion INTEGER NOT NULL REFERENCES Staff_Enum_Mentality (Value) ON UPDATE RESTRICT ON DELETE CASCADE, PRIMARY KEY (StaffID, Category));

CREATE TABLE Staff_Mentality_Events(EventID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, StaffID INTEGER NOT NULL REFERENCES Staff_GameData(StaffID) ON UPDATE RESTRICT ON DELETE CASCADE, Event INTEGER NOT NULL REFERENCES Staff_Enum_MentalityEvent(Value) ON UPDATE RESTRICT ON DELETE CASCADE, Opinion INTEGER NOT NULL REFERENCES Staff_Enum_Mentality(Value) ON UPDATE RESTRICT ON DELETE CASCADE, Value INTEGER NOT NULL, DecayDay INTEGER NOT NULL, ReferenceID INTEGER NOT NULL);

CREATE TABLE Staff_Mentality_Statuses (StaffID INTEGER NOT NULL REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, Status INTEGER NOT NULL REFERENCES Staff_Enum_MentalityStatus (Value) ON UPDATE RESTRICT ON DELETE CASCADE, Opinion INTEGER NOT NULL REFERENCES Staff_Enum_Mentality (Value) ON UPDATE RESTRICT ON DELETE CASCADE, Value INTEGER NOT NULL, PRIMARY KEY (StaffID, Status));

CREATE TABLE Staff_NarrativeData (StaffID INTEGER PRIMARY KEY REFERENCES Staff_BasicData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, GenSource INTEGER NOT NULL REFERENCES Staff_Enum_NarrativeGenSource (Value) ON DELETE CASCADE ON UPDATE RESTRICT, JobTitle TEXT NOT NULL, TeamID INTEGER REFERENCES Teams(TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, IsActive INTEGER NOT NULL DEFAULT 1);

CREATE TABLE Staff_PerformanceStats (StaffID INTEGER NOT NULL, StatID INTEGER NOT NULL, Val INTEGER NOT NULL DEFAULT 50, Max INTEGER NOT NULL DEFAULT (100), PRIMARY KEY (StaffID, StatID), FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (StatID) REFERENCES Staff_Enum_PerformanceStatTypes (Value));

CREATE TABLE Staff_PerformanceStats_StartOfMonth (StaffID INTEGER REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, StatID INTEGER REFERENCES Staff_Enum_PerformanceStatTypes (Value) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, Val INTEGER NOT NULL DEFAULT (50), PRIMARY KEY (StaffID, StatID));

CREATE TABLE Staff_PitCrew_DevelopmentPlan (TeamID INTEGER NOT NULL, Day INTEGER NOT NULL, TrainingSession INTEGER NOT NULL, TrainingType INTEGER, TrainingFocus INTEGER, PRIMARY KEY (TeamID, Day, TrainingSession), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TrainingType) REFERENCES Staff_Enum_PitCrewTrainingType (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TrainingSession) REFERENCES Staff_Enum_TrainingSession (Value) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT Check_TrainingSession CHECK (TrainingSession IN (0, 1)), FOREIGN KEY (TrainingFocus) REFERENCES Staff_Enum_PitCrewTrainingFocus (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_PitCrew_DevelopmentPlanGlobalData (TeamID INTEGER NOT NULL PRIMARY KEY, TrainingInProgress BOOLEAN DEFAULT (false) NOT NULL, TrainingCost BIGINT DEFAULT (0) NOT NULL, TrainingPreset INTEGER DEFAULT (1) NOT NULL, TrainingFocus INTEGER DEFAULT (0) NOT NULL, IsDirty BOOLEAN DEFAULT (false) NOT NULL, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TrainingPreset) REFERENCES Staff_Enum_PitCrewTrainingPreset (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TrainingFocus) REFERENCES Staff_Enum_PitCrewTrainingGlobalFocus (Value) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_PitCrew_PerformanceStats (TeamID INTEGER NOT NULL, StatID INTEGER NOT NULL, Val decimal (4, 1) NOT NULL, MonthStartVal DECIMAL (4, 1) NOT NULL, PRIMARY KEY (TeamID, StatID), FOREIGN KEY (StatID) REFERENCES Staff_Enum_PerformanceStatTypes (Value) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_PitCrew_RaceWeekendFatigue (TeamID INTEGER NOT NULL, Day INTEGER NOT NULL, Val DECIMAL (4, 1) NOT NULL, PRIMARY KEY (TeamID, Day), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_PitCrew_Statics (PitCrewDevelopmentLocked BOOLEAN DEFAULT (false) PRIMARY KEY);

CREATE TABLE Staff_RaceEngineerDriverAssignments (RaceEngineerID INTEGER NOT NULL, DriverID INTEGER NOT NULL, DaysTogether INTEGER NOT NULL DEFAULT 0, RelationshipLevel decimal (8, 3) NOT NULL DEFAULT 0.0, IsCurrentAssignment INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (DriverID, RaceEngineerID), FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (RaceEngineerID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_RaceRecord (StaffID INTEGER NOT NULL REFERENCES Staff_GameData(StaffID) ON UPDATE RESTRICT ON DELETE CASCADE, Formula INTEGER NOT NULL DEFAULT 1, TotalStarts INTEGER NOT NULL, TotalPodiums INTEGER NOT NULL, TotalWins INTEGER NOT NULL, TotalConstructorChampionships INTEGER NOT NULL, PRIMARY KEY(StaffID, Formula));

CREATE TABLE Staff_StaffTypePerformanceStatsTemplate (StaffType INTEGER NOT NULL,PerformanceStatType INTEGER NOT NULL,SeededValMin INTEGER NOT NULL,SeededValMax INTEGER NOT NULL,PRIMARY KEY (StaffType,PerformanceStatType),FOREIGN KEY (PerformanceStatType) REFERENCES Staff_Enum_PerformanceStatTypes (Value),FOREIGN KEY (StaffType) REFERENCES Staff_Enum_StaffType (StaffType) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Staff_State (StaffID INTEGER PRIMARY KEY UNIQUE NOT NULL, UnspentXP INTEGER NOT NULL DEFAULT (0), XPGainedLastRace INTEGER NOT NULL DEFAULT (0), XPGainedLastWeek INTEGER NOT NULL DEFAULT (0), Mentality INTEGER NOT NULL DEFAULT 50, MentalityOpinion INTEGER NOT NULL DEFAULT 2 REFERENCES Staff_Enum_Mentality (Value) ON UPDATE RESTRICT ON DELETE CASCADE, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Staff_SurnamePool (LocKey TEXT NOT NULL,Locale INTEGER NOT NULL DEFAULT 0,DriverCodeLocKey TEXT NOT NULL DEFAULT '[DriverCode_Placeholder]',FT0 INTEGER NOT NULL DEFAULT 1,FT1 INTEGER NOT NULL DEFAULT 1,FT2 INTEGER NOT NULL DEFAULT 1,FT3 INTEGER NOT NULL DEFAULT 1,FT4 INTEGER NOT NULL DEFAULT 1,PRIMARY KEY (LocKey,Locale),FOREIGN KEY (Locale) REFERENCES Staff_Enum_NameLocales (Value));

CREATE TABLE Staff_Team_CAS (StaffID INTEGER PRIMARY KEY NOT NULL REFERENCES Staff_BasicData (StaffID), TeamID INTEGER, PosInTeam INTEGER, FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE RESTRICT ON UPDATE CASCADE);

CREATE TABLE Staff_Traits (StaffID INTEGER NOT NULL, TraitID INTEGER NOT NULL, DayAdded INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (StaffID, TraitID), FOREIGN KEY (StaffID) REFERENCES Staff_GameData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (TraitID) REFERENCES Staff_Traits_Definitions (TraitID));

CREATE TABLE Staff_Traits_Constants (MinNumStartingTraits INTEGER NOT NULL PRIMARY KEY, MaxNumStartingTraits INTEGER NOT NULL, PermaTraitSpawnProbability decimal (4, 3) NOT NULL);

CREATE TABLE Staff_Traits_Definitions (TraitID INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL,LocKey TEXT NOT NULL DEFAULT '[StaffTrait_Name_]',Icon TEXT NOT NULL DEFAULT 'placeholder',Cause INTEGER DEFAULT NULL,CauseSpawnType INTEGER DEFAULT NULL,CauseSpawnParam decimal(8,3) DEFAULT NULL,Solution INTEGER DEFAULT NULL,Condition INTEGER DEFAULT NULL,ConditionParam TEXT DEFAULT NULL,DurationInDays INTEGER DEFAULT NULL,FOREIGN KEY (Cause) REFERENCES Staff_Enum_TraitCauses (Value),FOREIGN KEY (CauseSpawnType) REFERENCES Staff_Enum_TraitCauseSpawnTypes (Value),FOREIGN KEY (Condition) REFERENCES Staff_Enum_TraitConditions (Value),FOREIGN KEY (Solution) REFERENCES Staff_Enum_TraitSolutions (Value));

CREATE TABLE Staff_Traits_Effects (TraitID INTEGER NOT NULL,Effect decimal(6,3) NOT NULL,IsPercentage INTEGER NOT NULL DEFAULT 0,Target INTEGER NOT NULL,TargetPerformanceStat INTEGER DEFAULT NULL,FOREIGN KEY (Target) REFERENCES Staff_Enum_TraitTargets (Value),FOREIGN KEY (TargetPerformanceStat) REFERENCES Staff_Enum_PerformanceStatTypes (Value),FOREIGN KEY (TraitID) REFERENCES Staff_Traits_Definitions (TraitID));

CREATE TABLE Staff_Traits_Incompatibility (TraitID1 INTEGER NOT NULL,TraitID2 INTEGER NOT NULL,PRIMARY KEY (TraitID1,TraitID2),FOREIGN KEY (TraitID1) REFERENCES Staff_Traits_Definitions (TraitID),FOREIGN KEY (TraitID2) REFERENCES Staff_Traits_Definitions (TraitID));

CREATE TABLE Staff_Traits_Seeding (TraitID INTEGER NOT NULL,StaffType INTEGER NOT NULL,StartingTraitProbability decimal(3,2) NOT NULL DEFAULT 1.00,PRIMARY KEY (StaffType,TraitID),FOREIGN KEY (StaffType) REFERENCES Staff_Enum_StaffType (StaffType) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (TraitID) REFERENCES Staff_Traits_Definitions (TraitID));

CREATE TABLE SubTeam_Assignments (AssignmentID INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL,TeamID INTEGER NOT NULL,SubTeamType INTEGER NOT NULL,ActiveStaff INTEGER NOT NULL,AssignmentName text DEFAULT NULL,FOREIGN KEY (SubTeamType) REFERENCES SubTeam_Enum_Types (Type),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID));

CREATE TABLE SubTeam_Enum_Types (Type INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL, Name TEXT NOT NULL, HireCost bigint (20) NOT NULL, MonthlyRunCost bigint (20) NOT NULL, ModifierIncrease decimal (5, 2) NOT NULL);

CREATE TABLE SubTeam_Ownership (TeamID INTEGER NOT NULL,SubTeamType INTEGER NOT NULL,TotalStaff INTEGER NOT NULL,PRIMARY KEY (TeamID,SubTeamType),FOREIGN KEY (TeamID) REFERENCES Teams (TeamID),FOREIGN KEY (SubTeamType) REFERENCES SubTeam_Enum_Types (Type));

CREATE TABLE Teams (Formula INTEGER NOT NULL DEFAULT 1, PredictedRanking INTEGER NOT NULL, TeamID INTEGER UNIQUE PRIMARY KEY AUTOINCREMENT NOT NULL, TeamName TEXT NOT NULL, TeamNameLocKey TEXT NOT NULL, Location TEXT NOT NULL, ProfileText TEXT NOT NULL, SeasonsEnteredBeforeGameStart INTEGER DEFAULT NULL, FirstYearWithCurrentBranding INTEGER NOT NULL, IsCustomTeam INTEGER NOT NULL DEFAULT 0, CountryID INTEGER REFERENCES Countries (CountryID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Teams_AI_Records (TeamID INTEGER NOT NULL REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, SeasonID INTEGER REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT NOT NULL, PoachingAttempts INTEGER DEFAULT (0), SuccessfulPoachingAttempts INTEGER DEFAULT (0), SponsorSelectionDay INTEGER DEFAULT (0), LastDecisionEvaluationDay INTEGER DEFAULT (0), TotalDesignProjectsThisPeriod INTEGER DEFAULT (0), TotalResearchProjectsThisPeriod INTEGER DEFAULT (0), TotalIntenseDesignsThisPeriod INTEGER DEFAULT (0), TotalIntenseDesigns INTEGER DEFAULT (0), HasCastRegulationVote INTEGER DEFAULT (0), PRIMARY KEY (TeamID, SeasonID));

CREATE TABLE Teams_Colours (ColourID INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, TeamID INTEGER NOT NULL, Colour INTEGER NOT NULL, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Teams_Custom_Livery (LiveryType INTEGER PRIMARY KEY NOT NULL, DecalMaskIndex INTEGER DEFAULT (0), MaskRColorColour1 INTEGER DEFAULT (0), MaskRColorColour2 INTEGER DEFAULT (0), MaskRColorGradientRangeClampX REAL DEFAULT (0), MaskRColorGradientRangeClampY REAL DEFAULT (0), MaskRColorGradient TEXT DEFAULT '', MaskRColorMaterial TEXT DEFAULT '', MaskGColorColour1 INTEGER DEFAULT (0), MaskGColorColour2 INTEGER DEFAULT (0), MaskGColorGradientRangeClampX REAL DEFAULT (0), MaskGColorGradientRangeClampY REAL DEFAULT (0), MaskGColorGradient TEXT DEFAULT '', MaskGColorMaterial TEXT DEFAULT '', MaskBColorColour1 INTEGER DEFAULT (0), MaskBColorColour2 INTEGER DEFAULT (0), MaskBColorGradientRangeClampX REAL DEFAULT (0), MaskBColorGradientRangeClampY REAL DEFAULT (0), MaskBColorGradient TEXT DEFAULT '', MaskBColorMaterial TEXT DEFAULT '', DecalLayout TEXT DEFAULT '');

CREATE TABLE Teams_Custom_LiveryDecals (LiveryType INTEGER NOT NULL, SlotSponsorType INTEGER DEFAULT (0), "Key" TEXT DEFAULT '', AdjustmentPositionX REAL DEFAULT (0), AdjustmentPositionY REAL DEFAULT (0), AdjustmentRotation REAL DEFAULT (0), AdjustmentScale REAL DEFAULT (0), DecalType INTEGER DEFAULT (0), TeamLogoIndex INTEGER DEFAULT (0), SponsorID TEXT DEFAULT '', SlotSponsorLogoType INTEGER DEFAULT (0), TintColour INTEGER DEFAULT (0), Visible INTEGER DEFAULT (1));

CREATE TABLE Teams_Custom_LogoElements (ElementID INTEGER UNIQUE, PartHash INTEGER, Colour INTEGER, PositionX REAL, PositionY REAL, Rotation REAL, ScaleX REAL, ScaleY REAL);

CREATE TABLE Teams_MiscRecord (TeamID INTEGER UNIQUE PRIMARY KEY NOT NULL, HighestAnnualIncome bigint (20) NOT NULL, HighestAnnualIncomeYear INTEGER DEFAULT NULL, HighestTeamRating INTEGER NOT NULL, HighestTeamRatingYear INTEGER DEFAULT NULL);

CREATE TABLE Teams_PitCrewRecordBeforeGameStart (TeamID INTEGER NOT NULL, CompetitionWins INTEGER NOT NULL, FastestPitStopsTotal INTEGER NOT NULL, FastestPitStopTime DECIMAL (6, 3) NOT NULL, TotalPointsScored INTEGER NOT NULL, DriverID INTEGER NOT NULL, PRIMARY KEY (TeamID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Teams_PitCrewRecordPerSeason (TeamID INTEGER NOT NULL, SeasonID INTEGER NOT NULL, CompetitionWins INTEGER NOT NULL, FastestPitStopsTotal INTEGER NOT NULL, FastestPitStopTime DECIMAL (6, 3) NOT NULL, TotalPointsScored INTEGER NOT NULL, DriverID INTEGER NOT NULL, PRIMARY KEY (SeasonID, TeamID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Teams_PitCrewRecordSinceGameStart (TeamID INTEGER NOT NULL, CompetitionWins INTEGER DEFAULT (0) NOT NULL, FastestPitStopsTotal INTEGER DEFAULT (0) NOT NULL, FastestPitStopTime DECIMAL (6, 3) DEFAULT (0) NOT NULL, TotalPointsScored INTEGER DEFAULT (0) NOT NULL, DriverID INTEGER NOT NULL, PRIMARY KEY (TeamID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE ON UPDATE RESTRICT, FOREIGN KEY (DriverID) REFERENCES Staff_DriverData (StaffID) ON DELETE CASCADE ON UPDATE RESTRICT);

CREATE TABLE Teams_PriorityList (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,FeatureTypes INTEGER NOT NULL,NodeExecutionBehaviour INTEGER NOT NULL,DevelopCarPartSettingsID INTEGER DEFAULT NULL,DevelopBuildingSettingsID INTEGER DEFAULT NULL,DevelopStaffSettingsID INTEGER DEFAULT NULL,FOREIGN KEY (DevelopCarPartSettingsID) REFERENCES Teams_PriorityList_Setting_DevelopCarPartData (Value) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (FeatureTypes) REFERENCES Teams_PriorityList_Enum_FeatureTypes (Value) ON UPDATE CASCADE,FOREIGN KEY (NodeExecutionBehaviour) REFERENCES Teams_PriorityList_Enum_OnExecutionBehaviour (Value) ON UPDATE CASCADE,FOREIGN KEY (DevelopStaffSettingsID) REFERENCES Teams_PriorityList_Setting_DevelopStaffData (Value) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY (DevelopBuildingSettingsID) REFERENCES Teams_PriorityList_Setting_DevelopBuildingData (Value) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE Teams_PriorityList_Enum_FeatureTypes (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Teams_PriorityList_Enum_OnExecutionBehaviour (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,Name TEXT NOT NULL);

CREATE TABLE Teams_PriorityList_Setting_DevelopBuildingData (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,BuildingType INTEGER NOT NULL,Level INTEGER NOT NULL,DegrationThreshold decimal(3,2) DEFAULT NULL,FOREIGN KEY (BuildingType) REFERENCES Building_Enum_Types (Type));

CREATE TABLE Teams_PriorityList_Setting_DevelopCarPartData (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,AverageValue INTEGER NOT NULL,Speed INTEGER NOT NULL,FOREIGN KEY (Speed) REFERENCES Parts_Enum_DevSpeeds (Value));

CREATE TABLE Teams_PriorityList_Setting_DevelopStaffData (Value INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,StaffType INTEGER NOT NULL,MinAverage INTEGER NOT NULL,FOREIGN KEY (StaffType) REFERENCES Staff_Enum_StaffType (StaffType) ON DELETE CASCADE ON UPDATE CASCADE);

CREATE TABLE "Teams_RaceRecordBeforeGameStart" (TeamID INTEGER PRIMARY KEY NOT NULL, FirstRace INTEGER DEFAULT NULL, FirstRaceTrackID INTEGER DEFAULT NULL, LastRace INTEGER DEFAULT NULL, LastRaceTrackID INTEGER DEFAULT NULL, FirstWin INTEGER DEFAULT NULL, FirstWinTrackID INTEGER DEFAULT NULL, LastWin INTEGER DEFAULT NULL, LastWinTrackID INTEGER DEFAULT NULL, FirstPodium INTEGER DEFAULT NULL, FirstPodiumTrackID INTEGER DEFAULT NULL, FirstPoints INTEGER DEFAULT NULL, FirstPointsTrackID INTEGER DEFAULT NULL, TotalDriverStarts INTEGER NOT NULL DEFAULT 0, TotalDriverFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverQualifying INTEGER NOT NULL DEFAULT 0, BestQualifyingYear INTEGER DEFAULT NULL, BestQualifying INTEGER DEFAULT NULL, BestQualifyingTrackID INTEGER DEFAULT NULL, BestFinish INTEGER DEFAULT NULL, BestFinishYear INTEGER DEFAULT NULL, BestFinishTrackID INTEGER DEFAULT NULL, TotalDriverSprintWins INTEGER NOT NULL DEFAULT (0), TotalDriverPoles INTEGER NOT NULL DEFAULT 0, TotalDriverWins INTEGER NOT NULL DEFAULT 0, TotalDriverPodiums INTEGER NOT NULL DEFAULT 0, TotalDriverPointsScoringFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverPoints INTEGER NOT NULL DEFAULT 0, TotalDriverFastestLaps INTEGER NOT NULL DEFAULT 0, BestDriverFinishes INTEGER NOT NULL DEFAULT 0, BestDriverChampionshipPlace INTEGER DEFAULT NULL, BestDriverChampionshipYear INTEGER DEFAULT NULL, TotalDriverChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalDriverChampionshipPodiums INTEGER NOT NULL DEFAULT 0, BestConstructorChampionshipPlace INTEGER DEFAULT NULL, BestConstructorChampionshipYear INTEGER DEFAULT NULL, TotalConstructorChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalConstructorChampionshipPodiums INTEGER NOT NULL DEFAULT 0, TotalUniqueStarts INTEGER NOT NULL DEFAULT (0), TotalUniqueFinishes INTEGER NOT NULL DEFAULT 0, TotalUniquePodiums INTEGER NOT NULL DEFAULT 0, BestSprintFinish INTEGER DEFAULT NULL, BestSprintFinishYear INTEGER DEFAULT NULL, BestSprintFinishTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks(TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FOREIGN KEY (BestFinishTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (BestQualifyingTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPodiumTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPointsTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE);

CREATE TABLE Teams_RaceRecordPerSeason (TeamID INTEGER NOT NULL, SeasonID INTEGER NOT NULL, FirstRace INTEGER DEFAULT NULL, FirstRaceTrackID INTEGER DEFAULT NULL, LastRace INTEGER DEFAULT NULL, LastRaceTrackID INTEGER DEFAULT NULL, FirstWin INTEGER DEFAULT NULL, FirstWinTrackID INTEGER DEFAULT NULL, LastWin INTEGER DEFAULT NULL, LastWinTrackID INTEGER DEFAULT NULL, FirstPodium INTEGER DEFAULT NULL, FirstPodiumTrackID INTEGER DEFAULT NULL, FirstPoints INTEGER DEFAULT NULL, FirstPointsTrackID INTEGER DEFAULT NULL, TotalDriverStarts INTEGER NOT NULL DEFAULT 0, TotalDriverFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverQualifying INTEGER NOT NULL DEFAULT 0, BestQualifyingYear INTEGER DEFAULT NULL, BestQualifying INTEGER DEFAULT NULL, BestQualifyingTrackID INTEGER DEFAULT NULL, BestFinish INTEGER DEFAULT NULL, BestFinishYear INTEGER DEFAULT NULL, BestFinishTrackID INTEGER DEFAULT NULL, TotalDriverSprintWins INTEGER DEFAULT (0) NOT NULL, TotalDriverPoles INTEGER NOT NULL DEFAULT 0, TotalDriverWins INTEGER NOT NULL DEFAULT 0, TotalDriverPodiums INTEGER NOT NULL DEFAULT 0, TotalDriverPointsScoringFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverPoints INTEGER NOT NULL DEFAULT 0, TotalDriverFastestLaps INTEGER NOT NULL DEFAULT 0, BestDriverFinishes INTEGER NOT NULL DEFAULT 0, BestDriverChampionshipPlace INTEGER DEFAULT NULL, BestDriverChampionshipYear INTEGER DEFAULT NULL, TotalDriverChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalDriverChampionshipPodiums INTEGER NOT NULL DEFAULT 0, BestConstructorChampionshipPlace INTEGER DEFAULT NULL, BestConstructorChampionshipYear INTEGER DEFAULT NULL, TotalConstructorChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalConstructorChampionshipPodiums INTEGER NOT NULL DEFAULT 0, TotalUniqueStarts INTEGER NOT NULL DEFAULT 0, TotalUniqueFinishes INTEGER NOT NULL DEFAULT 0, TotalUniquePodiums INTEGER NOT NULL DEFAULT 0, BestSprintFinish INTEGER DEFAULT NULL, BestSprintFinishYear INTEGER DEFAULT NULL, BestSprintFinishTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks(TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, PRIMARY KEY (TeamID, SeasonID), FOREIGN KEY (BestFinishTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (BestQualifyingTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPodiumTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPointsTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (SeasonID) REFERENCES Seasons (SeasonID) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE);

CREATE TABLE Teams_RaceRecordSinceGameStart (TeamID INTEGER PRIMARY KEY NOT NULL, FirstRace INTEGER DEFAULT NULL, FirstRaceTrackID INTEGER DEFAULT NULL, LastRace INTEGER DEFAULT NULL, LastRaceTrackID INTEGER DEFAULT NULL, FirstWin INTEGER DEFAULT NULL, FirstWinTrackID INTEGER DEFAULT NULL, LastWin INTEGER DEFAULT NULL, LastWinTrackID INTEGER DEFAULT NULL, FirstPodium INTEGER DEFAULT NULL, FirstPodiumTrackID INTEGER DEFAULT NULL, FirstPoints INTEGER DEFAULT NULL, FirstPointsTrackID INTEGER DEFAULT NULL, TotalDriverStarts INTEGER NOT NULL DEFAULT 0, TotalDriverFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverQualifying INTEGER NOT NULL DEFAULT 0, BestQualifyingYear INTEGER DEFAULT NULL, BestQualifying INTEGER DEFAULT NULL, BestQualifyingTrackID INTEGER DEFAULT NULL, BestFinish INTEGER DEFAULT NULL, BestFinishYear INTEGER DEFAULT NULL, BestFinishTrackID INTEGER DEFAULT NULL, TotalDriverSprintWins INTEGER NOT NULL DEFAULT (0), TotalDriverPoles INTEGER NOT NULL DEFAULT 0, TotalDriverWins INTEGER NOT NULL DEFAULT 0, TotalDriverPodiums INTEGER NOT NULL DEFAULT 0, TotalDriverPointsScoringFinishes INTEGER NOT NULL DEFAULT 0, TotalDriverPoints INTEGER NOT NULL DEFAULT 0, TotalDriverFastestLaps INTEGER NOT NULL DEFAULT 0, BestDriverFinishes INTEGER NOT NULL DEFAULT 0, BestDriverChampionshipPlace INTEGER DEFAULT NULL, BestDriverChampionshipYear INTEGER DEFAULT NULL, TotalDriverChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalDriverChampionshipPodiums INTEGER NOT NULL DEFAULT 0, BestConstructorChampionshipPlace INTEGER DEFAULT NULL, BestConstructorChampionshipYear INTEGER DEFAULT NULL, TotalConstructorChampionshipWins INTEGER NOT NULL DEFAULT 0, TotalConstructorChampionshipPodiums INTEGER NOT NULL DEFAULT 0, TotalUniqueStarts INTEGER NOT NULL DEFAULT 0, TotalUniqueFinishes INTEGER NOT NULL DEFAULT 0, TotalUniquePodiums INTEGER NOT NULL DEFAULT 0, BestSprintFinish INTEGER DEFAULT NULL, BestSprintFinishYear INTEGER DEFAULT NULL, BestSprintFinishTrackID INTEGER DEFAULT NULL REFERENCES Races_Tracks(TrackID) ON UPDATE RESTRICT ON DELETE CASCADE, FOREIGN KEY (BestFinishTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (BestQualifyingTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPodiumTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstPointsTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (FirstWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastRaceTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (LastWinTrackID) REFERENCES Races_Tracks (TrackID), FOREIGN KEY (TeamID) REFERENCES Teams (TeamID) ON DELETE CASCADE);

CREATE TABLE sqlite_sequence(name,seq);

CREATE TABLE sqlite_stat1(tbl,idx,stat);

-- ============ VIEWS ============

CREATE VIEW Staff_Contracts_View AS SELECT 
    Teams.TeamName,
    Teams.Formula,
    Staff_BasicData.FirstName, 
    Staff_BasicData.LastName, 
    Staff_Contracts.* 
FROM 
    Staff_Contracts 
    JOIN Staff_BasicData ON Staff_Contracts.StaffID = Staff_BasicData.StaffID
    JOIN Teams ON Staff_Contracts.TeamID = Teams.TeamID;

CREATE VIEW Staff_DriverData_View AS SELECT Staff_BasicData.FirstName, Staff_BasicData.Lastname, Staff_DriverData.* FROM Staff_BasicData JOIN Staff_DriverData ON Staff_BasicData.StaffID = Staff_DriverData.StaffID;

-- ============ INDEXES ============

CREATE INDEX idx_Custom_Engine_Progression_Season_Engine_Race
    ON Custom_Engine_Progression (SeasonID, EngineID, RaceID)
  ;

